package main

import (
	"encoding/gob"
	"fmt"
	"os"
	"sort"
	"time"
)

type IdsMap map[string]int
type Query struct {
	Cmd           string
	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Due           time.Time
	DateFilter    string
	Priority      string
	Template      int
	Text          string
	IgnoreContext bool
	Note          string
}
type State struct {
	Context Query
}

func main() {
	f, err := os.Open(os.Args[1])
	if err != nil {
		fmt.Println(err)
		return
	}
	if len(os.Args) > 2 && os.Args[2] == "state" {
		var s State
		err = gob.NewDecoder(f).Decode(&s)
		fmt.Printf("%v %+v\n", err, s)
		return
	}
	m := IdsMap{}
	err = gob.NewDecoder(f).Decode(&m)
	if err != nil {
		fmt.Println(err)
	}
	keys := []string{}
	for k := range m {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool { return m[keys[i]] < m[keys[j]] })
	for _, k := range keys {
		fmt.Println(m[k], k)
	}
}
EOF
