{"command":"cd /workspace; cat > query.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"
)

type Query struct {
	Cmd           string
	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Due           time.Time
	DateFilter    string
	Priority      string
	Template      int
	Text          string
	IgnoreContext bool
	Note          string
}

func ParseQuery(args ...string) (Query, error) {
	var cmd string
	ids := []int{}
	tags := []string{}
	antiTags := []string{}
	var project string
	antiProjects := []string{}
	var priority string
	var template int
	var words []string
	var notesModeActivated bool
	var notes []string
	var ignoreContext bool
	var dueDate time.Time
	var dateFilter string

	idsExhausted := false

	for _, item := range args {
		lcItem := strings.ToLower(item)

		if notesModeActivated {
			notes = append(notes, item)
			continue
		}

		if cmd == "" && isCommand(lcItem) {
			cmd = lcItem
			continue
		}

		if !idsExhausted {
			if s, err := strconv.ParseInt(item, 10, 64); err == nil {
				ids = append(ids, int(s))
				continue
			}
		}

		idsExhausted = true

		if item == IGNORE_CONTEXT_KEYWORD {
			ignoreContext = true
		} else if item == NOTE_MODE_KEYWORD {
			notesModeActivated = true
		} else if project == "" && strings.HasPrefix(lcItem, "project:") {
			project = lcItem[8:]
		} else if strings.HasPrefix(lcItem, "-project:") {
			antiProjects = append(antiProjects, lcItem[9:])
		} else if strings.HasPrefix(lcItem, "due.") || strings.HasPrefix(lcItem, "due:") {
			if !dueDate.IsZero() {
				return Query{}, errors.New("Query should only have one due date")
			}
			filter, due, err := parseDueArg(lcItem)
			if err != nil {
				return Query{}, err
			}
			dateFilter = filter
			dueDate = due
		} else if strings.HasPrefix(lcItem, "template:") {
			if s, err := strconv.ParseInt(lcItem[9:], 10, 64); err == nil {
				template = int(s)
			}
		} else if len(item) > 1 && lcItem[0] == '+' {
			tags = append(tags, lcItem[1:])
		} else if len(item) > 1 && lcItem[0] == '-' {
			antiTags = append(antiTags, lcItem[1:])
		} else if priority == "" && isValidPriority(item) {
			priority = item
		} else {
			words = append(words, item)
		}
	}

	return Query{
		Cmd:           cmd,
		IDs:           ids,
		Tags:          tags,
		AntiTags:      antiTags,
		Project:       project,
		AntiProjects:  antiProjects,
		Due:           dueDate,
		DateFilter:    dateFilter,
		Priority:      priority,
		Template:      template,
		Text:          strings.Join(words, " "),
		IgnoreContext: ignoreContext,
		Note:          strings.Join(notes, " "),
	}, nil
}

func parseDueArg(lcItem string) (string, time.Time, error) {
	parts := strings.SplitN(lcItem, ":", 2)
	if len(parts) != 2 {
		return "", time.Time{}, fmt.Errorf("Invalid due query format: %s\nExpected format: due:YYYY-MM-DD, due:MM-DD, due:DD, due:next-monday, due:today, etc.", lcItem)
	}
	filter := strings.TrimPrefix(parts[0], "due")
	filter = strings.TrimPrefix(filter, ".")
	switch filter {
	case "", "after", "before", "on", "in":
	default:
		return "", time.Time{}, fmt.Errorf("Invalid date filter format: %s\nValid filters are: after, before, on, in", filter)
	}
	if parts[1] == "overdue" {
		return "before", startOfDay(time.Now()), nil
	}
	due, err := parseDueDate(parts[1])
	if err != nil {
		return "", time.Time{}, err
	}
	return filter, due, nil
}

func startOfDay(t time.Time) time.Time {
	return time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, t.Location())
}

var weekdayNames = map[string]time.Weekday{
	"sunday":    time.Sunday,
	"sun":       time.Sunday,
	"monday":    time.Monday,
	"mon":       time.Monday,
	"tuesday":   time.Tuesday,
	"tue":       time.Tuesday,
	"tues":      time.Tuesday,
	"wednesday": time.Wednesday,
	"wed":       time.Wednesday,
	"thursday":  time.Thursday,
	"thu":       time.Thursday,
	"thur":      time.Thursday,
	"thurs":     time.Thursday,
	"friday":    time.Friday,
	"fri":       time.Friday,
	"saturday":  time.Saturday,
	"sat":       time.Saturday,
}

func parseDueDate(s string) (time.Time, error) {
	now := time.Now()
	today := startOfDay(now)
	switch s {
	case "today":
		return today, nil
	case "tomorrow":
		return today.AddDate(0, 0, 1), nil
	case "yesterday":
		return today.AddDate(0, 0, -1), nil
	}

	prefix := "this"
	name := s
	if i := strings.Index(s, "-"); i > 0 {
		p := s[:i]
		if p == "this" || p == "next" || p == "last" {
			prefix = p
			name = s[i+1:]
		}
	}
	if wd, ok := weekdayNames[name]; ok {
		todayWD := int(today.Weekday())
		startOfWeek := today.AddDate(0, 0, -todayWD)
		switch prefix {
		case "this":
			return today.AddDate(0, 0, (int(wd)-todayWD+7)%7), nil
		case "next":
			return startOfWeek.AddDate(0, 0, 7+int(wd)), nil
		case "last":
			return startOfWeek.AddDate(0, 0, int(wd)), nil
		}
	}

	if t, err := time.Parse("2006-01-02", s); err == nil {
		return time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, time.Local), nil
	}
	if t, err := time.Parse("01-02", s); err == nil {
		return time.Date(now.Year(), t.Month(), t.Day(), 0, 0, 0, 0, time.Local), nil
	}
	if t, err := time.Parse("2", s); err == nil {
		return time.Date(now.Year(), now.Month(), t.Day(), 0, 0, 0, 0, time.Local), nil
	}

	return time.Time{}, fmt.Errorf("Invalid due date format: %s\nExpected format: YYYY-MM-DD, MM-DD or DD, relative date like 'next-monday', 'today', etc.", s)
}

func (q Query) String() string {
	var args []string
	for _, id := range q.IDs {
		args = append(args, strconv.Itoa(id))
	}
	for _, tag := range q.Tags {
		args = append(args, "+"+tag)
	}
	for _, tag := range q.AntiTags {
		args = append(args, "-"+tag)
	}
	if q.Project != "" {
		args = append(args, "project:"+q.Project)
	}
	for _, p := range q.AntiProjects {
		args = append(args, "-project:"+p)
	}
	if !q.Due.IsZero() {
		d := q.Due.Format("2006-01-02")
		if q.DateFilter == "" {
			args = append(args, "due:"+d)
		} else {
			args = append(args, "due."+q.DateFilter+":"+d)
		}
	}
	if q.Priority != "" {
		args = append(args, q.Priority)
	}
	if q.Template > 0 {
		args = append(args, "template:"+strconv.Itoa(q.Template))
	}
	if q.Text != "" {
		args = append(args, "\""+q.Text+"\"")
	}
	return strings.Join(args, " ")
}

func (q Query) HasOperators() bool {
	return len(q.Tags) > 0 ||
		len(q.AntiTags) > 0 ||
		q.Project != "" ||
		len(q.AntiProjects) > 0 ||
		q.Priority != "" ||
		q.Template > 0 ||
		!q.Due.IsZero()
}

// Merge applies the context q2 onto q
func (q Query) Merge(q2 Query) (Query, error) {
	out := q
	out.Tags = append(append([]string{}, q.Tags...), q2.Tags...)
	out.AntiTags = append(append([]string{}, q.AntiTags...), q2.AntiTags...)

	if q2.Project != "" {
		if q.Project != "" && q.Project != q2.Project {
			return q, errors.New("Could not apply q2, project conflict")
		}
		out.Project = q2.Project
	}

	out.AntiProjects = append(append([]string{}, q.AntiProjects...), q2.AntiProjects...)

	if q2.Priority != "" {
		if q.Priority != "" && q.Priority != q2.Priority {
			return q, errors.New("Could not apply q2, priority conflict")
		}
		out.Priority = q2.Priority
	}

	if !q2.Due.IsZero() {
		if !q.Due.IsZero() && (!q.Due.Equal(q2.Due) || q.DateFilter != q2.DateFilter) {
			return q, errors.New("Could not apply q2, date filter conflict")
		}
		out.Due = q2.Due
		out.DateFilter = q2.DateFilter
	}

	return out, nil
}
EOF"}

