cd /workspace; cat > yamlemit.go <<'EOF'
package main

// A minimal port of the scalar-emitting logic of go-yaml v2's emitter, enough
// to serialise tasks byte-for-byte identically.

import (
	"bytes"
	"math"
	"regexp"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

const (
	styleAny = iota
	stylePlain
	styleSingle
	styleDouble
	styleLiteral
)

type yemitter struct {
	buf         bytes.Buffer
	column      int
	indent      int
	whitespace  bool
	indention   bool
	bestWidth   int
	bestIndent  int
	flowLevel   int
	indents     []int
	openEnded   bool
	mappingCtx  bool
	simpleKey   bool
}

func newYEmitter() *yemitter {
	return &yemitter{indent: -1, whitespace: true, indention: true, bestWidth: 80, bestIndent: 2}
}

// ---- byte helpers (as in yamlprivateh.go) ----

func yIsSpace(b []byte, i int) bool { return i < len(b) && b[i] == ' ' }
func yIsTab(b []byte, i int) bool   { return i < len(b) && b[i] == '\t' }
func yIsBlank(b []byte, i int) bool { return i < len(b) && (b[i] == ' ' || b[i] == '\t') }
func yIsBreak(b []byte, i int) bool {
	if i >= len(b) {
		return false
	}
	return b[i] == '\r' || b[i] == '\n' ||
		(b[i] == 0xC2 && i+1 < len(b) && b[i+1] == 0x85) ||
		(b[i] == 0xE2 && i+2 < len(b) && b[i+1] == 0x80 && b[i+2] == 0xA8) ||
		(b[i] == 0xE2 && i+2 < len(b) && b[i+1] == 0x80 && b[i+2] == 0xA9)
}
func yIsBlankz(b []byte, i int) bool {
	return i >= len(b) || b[i] == 0 || yIsBlank(b, i) || yIsBreak(b, i)
}
func yAt(b []byte, i int) byte {
	if i < len(b) {
		return b[i]
	}
	return 0
}
func yIsPrintable(b []byte, i int) bool {
	c := b[i]
	return c == 0x0A ||
		(c >= 0x20 && c <= 0x7E) ||
		(c == 0xC2 && yAt(b, i+1) >= 0xA0) ||
		(c > 0xC2 && c < 0xED) ||
		(c == 0xED && yAt(b, i+1) < 0xA0) ||
		(c == 0xEE) ||
		(c == 0xEF &&
			!(yAt(b, i+1) == 0xBB && yAt(b, i+2) == 0xBF) &&
			!(yAt(b, i+1) == 0xBF && (yAt(b, i+2) == 0xBE || yAt(b, i+2) == 0xBF)))
}
func yIsBOM(b []byte, i int) bool {
	return i+2 < len(b) && b[i] == 0xEF && b[i+1] == 0xBB && b[i+2] == 0xBF
}
func yWidth(c byte) int {
	switch {
	case c&0x80 == 0x00:
		return 1
	case c&0xE0 == 0xC0:
		return 2
	case c&0xF0 == 0xE0:
		return 3
	case c&0xF8 == 0xF0:
		return 4
	}
	return 0
}

// ---- low level writes ----

func (e *yemitter) put(c byte) {
	e.buf.WriteByte(c)
	e.column++
}

func (e *yemitter) putBreak() {
	e.buf.WriteByte('\n')
	e.column = 0
}

func (e *yemitter) write(s []byte, i *int) {
	w := yWidth(s[*i])
	if w == 0 {
		w = 1
	}
	if *i+w > len(s) {
		w = len(s) - *i
	}
	e.buf.Write(s[*i : *i+w])
	e.column++
	*i += w
}

func (e *yemitter) writeBreak(s []byte, i *int) {
	if s[*i] == '\n' {
		e.putBreak()
		*i++
	} else {
		e.write(s, i)
		e.column = 0
	}
}

func (e *yemitter) writeIndent() {
	indent := e.indent
	if indent < 0 {
		indent = 0
	}
	if !e.indention || e.column > indent || (e.column == indent && !e.whitespace) {
		e.putBreak()
	}
	for e.column < indent {
		e.put(' ')
	}
	e.whitespace = true
	e.indention = true
}

func (e *yemitter) writeIndicator(ind string, needWhitespace, isWhitespace, isIndention bool) {
	if needWhitespace && !e.whitespace {
		e.put(' ')
	}
	b := []byte(ind)
	for i := 0; i < len(b); {
		e.write(b, &i)
	}
	e.whitespace = isWhitespace
	e.indention = e.indention && isIndention
	e.openEnded = false
}

func (e *yemitter) increaseIndent(flow, indentless bool) {
	e.indents = append(e.indents, e.indent)
	if e.indent < 0 {
		if flow {
			e.indent = e.bestIndent
		} else {
			e.indent = 0
		}
	} else if !indentless {
		e.indent += e.bestIndent
	}
}

func (e *yemitter) popIndent() {
	e.indent = e.indents[len(e.indents)-1]
	e.indents = e.indents[:len(e.indents)-1]
}

// ---- scalar analysis ----

type scalarAnalysis struct {
	multiline           bool
	flowPlainAllowed    bool
	blockPlainAllowed   bool
	singleQuotedAllowed bool
	blockAllowed        bool
}

func analyzeScalar(value []byte) scalarAnalysis {
	var a scalarAnalysis
	if len(value) == 0 {
		a.multiline = false
		a.flowPlainAllowed = false
		a.blockPlainAllowed = true
		a.singleQuotedAllowed = true
		a.blockAllowed = false
		return a
	}

	var blockIndicators, flowIndicators, lineBreaks, specialCharacters bool
	var leadingSpace, leadingBreak, trailingSpace, trailingBreak, breakSpace, spaceBreak bool
	var precededByWhitespace, followedByWhitespace, previousSpace, previousBreak bool

	if len(value) >= 3 && ((value[0] == '-' && value[1] == '-' && value[2] == '-') || (value[0] == '.' && value[1] == '.' && value[2] == '.')) {
		blockIndicators = true
		flowIndicators = true
	}

	precededByWhitespace = true
	for i, w := 0, 0; i < len(value); i += w {
		w = yWidth(value[i])
		if w == 0 {
			w = 1
		}
		followedByWhitespace = i+w >= len(value) || yIsBlank(value, i+w)

		if i == 0 {
			switch value[i] {
			case '#', ',', '[', ']', '{', '}', '&', '*', '!', '|', '>', '\'', '"', '%', '@', '`':
				flowIndicators = true
				blockIndicators = true
			case '?', ':':
				flowIndicators = true
				if followedByWhitespace {
					blockIndicators = true
				}
			case '-':
				if followedByWhitespace {
					flowIndicators = true
					blockIndicators = true
				}
			}
		} else {
			switch value[i] {
			case ',', '?', '[', ']', '{', '}':
				flowIndicators = true
			case ':':
				flowIndicators = true
				if followedByWhitespace {
					blockIndicators = true
				}
			case '#':
				if precededByWhitespace {
					flowIndicators = true
					blockIndicators = true
				}
			}
		}

		// emitter.unicode is true, so only non-printables are special
		if !yIsPrintable(value, i) {
			specialCharacters = true
		}
		if yIsSpace(value, i) {
			if i == 0 {
				leadingSpace = true
			}
			if i+w == len(value) {
				trailingSpace = true
			}
			if previousBreak {
				breakSpace = true
			}
			previousSpace = true
			previousBreak = false
		} else if yIsBreak(value, i) {
			lineBreaks = true
			if i == 0 {
				leadingBreak = true
			}
			if i+w == len(value) {
				trailingBreak = true
			}
			if previousSpace {
				spaceBreak = true
			}
			previousSpace = false
			previousBreak = true
		} else {
			previousSpace = false
			previousBreak = false
		}

		precededByWhitespace = yIsBlankz(value, i)
	}

	a.multiline = lineBreaks
	a.flowPlainAllowed = true
	a.blockPlainAllowed = true
	a.singleQuotedAllowed = true
	a.blockAllowed = true

	if leadingSpace || leadingBreak || trailingSpace || trailingBreak {
		a.flowPlainAllowed = false
		a.blockPlainAllowed = false
	}
	if trailingSpace {
		a.blockAllowed = false
	}
	if breakSpace {
		a.flowPlainAllowed = false
		a.blockPlainAllowed = false
		a.singleQuotedAllowed = false
	}
	if spaceBreak || specialCharacters {
		a.flowPlainAllowed = false
		a.blockPlainAllowed = false
		a.singleQuotedAllowed = false
		a.blockAllowed = false
	}
	if lineBreaks {
		a.flowPlainAllowed = false
		a.blockPlainAllowed = false
	}
	if flowIndicators {
		a.flowPlainAllowed = false
	}
	if blockIndicators {
		a.blockPlainAllowed = false
	}
	return a
}

// ---- resolve (to decide whether a plain string would be read back as non-string) ----

var yamlStyleFloat = regexp.MustCompile(`^[-+]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][-+]?[0-9]+)?$`)
var base60float = regexp.MustCompile(`^[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+(?:\.[0-9_]*)?$`)

var resolveMapV2 = map[string]string{}

func init() {
	for _, s := range []string{"y", "Y", "yes", "Yes", "YES", "true", "True", "TRUE", "on", "On", "ON",
		"n", "N", "no", "No", "NO", "false", "False", "FALSE", "off", "Off", "OFF"} {
		resolveMapV2[s] = "bool"
	}
	for _, s := range []string{"", "~", "null", "Null", "NULL"} {
		resolveMapV2[s] = "null"
	}
	for _, s := range []string{".nan", ".NaN", ".NAN", ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF", "-.inf", "-.Inf", "-.INF"} {
		resolveMapV2[s] = "float"
	}
	resolveMapV2["<<"] = "merge"
}

func resolveHint(c byte) byte {
	switch {
	case c == '+' || c == '-':
		return 'S'
	case c >= '0' && c <= '9':
		return 'D'
	case strings.IndexByte("yYnNtTfFoO~", c) >= 0:
		return 'M'
	case c == '.':
		return '.'
	case c == '<':
		return 'M'
	}
	return 0
}

var allowedTimestampFormats = []string{
	"2006-1-2T15:4:5.999999999Z07:00",
	"2006-1-2t15:4:5.999999999Z07:00",
	"2006-1-2 15:4:5.999999999",
	"2006-1-2",
}

func yamlParseTimestamp(s string) (time.Time, bool) {
	i := 0
	for ; i < len(s); i++ {
		if c := s[i]; c < '0' || c > '9' {
			break
		}
	}
	if i != 4 || i == len(s) || s[i] != '-' {
		return time.Time{}, false
	}
	for _, format := range allowedTimestampFormats {
		if t, err := time.Parse(format, s); err == nil {
			return t, true
		}
	}
	return time.Time{}, false
}

// resolveTag returns the implicit tag of a plain scalar ("str", "int", ...)
func resolveTag(in string) string {
	hint := byte('N')
	if in != "" {
		hint = resolveHint(in[0])
	}
	if hint == 0 {
		return "str"
	}
	if t, ok := resolveMapV2[in]; ok {
		return t
	}
	switch hint {
	case 'M':
	case '.':
		if _, err := strconv.ParseFloat(in, 64); err == nil {
			return "float"
		}
	case 'D', 'S':
		if _, ok := yamlParseTimestamp(in); ok {
			return "timestamp"
		}
		plain := strings.Replace(in, "_", "", -1)
		if _, err := strconv.ParseInt(plain, 0, 64); err == nil {
			return "int"
		}
		if _, err := strconv.ParseUint(plain, 0, 64); err == nil {
			return "int"
		}
		if yamlStyleFloat.MatchString(plain) {
			if _, err := strconv.ParseFloat(plain, 64); err == nil {
				return "float"
			}
		}
		if strings.HasPrefix(plain, "0b") {
			if _, err := strconv.ParseInt(plain[2:], 2, 64); err == nil {
				return "int"
			}
			if _, err := strconv.ParseUint(plain[2:], 2, 64); err == nil {
				return "int"
			}
		} else if strings.HasPrefix(plain, "-0b") {
			if _, err := strconv.ParseInt("-"+plain[3:], 2, 64); err == nil {
				return "int"
			}
		}
	}
	_ = math.Inf
	return "str"
}

func isBase60Float(s string) bool {
	if s == "" {
		return false
	}
	c := s[0]
	if !(c == '+' || c == '-' || c >= '0' && c <= '9') || strings.IndexByte(s, ':') < 0 {
		return false
	}
	return base60float.MatchString(s)
}

// ---- scalar writers ----

func (e *yemitter) writePlain(value []byte, allowBreaks bool) {
	if !e.whitespace {
		e.put(' ')
	}
	spaces := false
	breaks := false
	for i := 0; i < len(value); {
		if yIsSpace(value, i) {
			if allowBreaks && !spaces && e.column > e.bestWidth && !yIsSpace(value, i+1) {
				e.writeIndent()
				i += yWidth(value[i])
			} else {
				e.write(value, &i)
			}
			spaces = true
		} else if yIsBreak(value, i) {
			if !breaks && value[i] == '\n' {
				e.putBreak()
			}
			e.writeBreak(value, &i)
			e.indention = true
			breaks = true
		} else {
			if breaks {
				e.writeIndent()
			}
			e.write(value, &i)
			e.indention = false
			spaces = false
			breaks = false
		}
	}
	e.whitespace = false
	e.indention = false
}

func (e *yemitter) writeSingleQuoted(value []byte, allowBreaks bool) {
	e.writeIndicator("'", true, false, false)
	spaces := false
	breaks := false
	for i := 0; i < len(value); {
		if yIsSpace(value, i) {
			if allowBreaks && !spaces && e.column > e.bestWidth && i > 0 && i < len(value)-1 && !yIsSpace(value, i+1) {
				e.writeIndent()
				i += yWidth(value[i])
			} else {
				e.write(value, &i)
			}
			spaces = true
		} else if yIsBreak(value, i) {
			if !breaks && value[i] == '\n' {
				e.putBreak()
			}
			e.writeBreak(value, &i)
			e.indention = true
			breaks = true
		} else {
			if breaks {
				e.writeIndent()
			}
			if value[i] == '\'' {
				e.put('\'')
			}
			e.write(value, &i)
			e.indention = false
			spaces = false
			breaks = false
		}
	}
	e.writeIndicator("'", false, false, false)
	e.whitespace = false
	e.indention = false
}

func (e *yemitter) writeDoubleQuoted(value []byte, allowBreaks bool) {
	spaces := false
	e.writeIndicator("\"", true, false, false)
	for i := 0; i < len(value); {
		if !yIsPrintable(value, i) || yIsBOM(value, i) || yIsBreak(value, i) || value[i] == '"' || value[i] == '\\' {
			octet := value[i]
			var w int
			var v rune
			switch {
			case octet&0x80 == 0x00:
				w, v = 1, rune(octet&0x7F)
			case octet&0xE0 == 0xC0:
				w, v = 2, rune(octet&0x1F)
			case octet&0xF0 == 0xE0:
				w, v = 3, rune(octet&0x0F)
			case octet&0xF8 == 0xF0:
				w, v = 4, rune(octet&0x07)
			default:
				w, v = 1, rune(octet)
			}
			for k := 1; k < w && i+k < len(value); k++ {
				octet = value[i+k]
				v = (v << 6) + (rune(octet) & 0x3F)
			}
			i += w

			e.put('\\')
			switch v {
			case 0x00:
				e.put('0')
			case 0x07:
				e.put('a')
			case 0x08:
				e.put('b')
			case 0x09:
				e.put('t')
			case 0x0A:
				e.put('n')
			case 0x0b:
				e.put('v')
			case 0x0c:
				e.put('f')
			case 0x0d:
				e.put('r')
			case 0x1b:
				e.put('e')
			case 0x22:
				e.put('"')
			case 0x5c:
				e.put('\\')
			case 0x85:
				e.put('N')
			case 0xA0:
				e.put('_')
			case 0x2028:
				e.put('L')
			case 0x2029:
				e.put('P')
			default:
				if v <= 0xFF {
					e.put('x')
					w = 2
				} else if v <= 0xFFFF {
					e.put('u')
					w = 4
				} else {
					e.put('U')
					w = 8
				}
				for k := (w - 1) * 4; k >= 0; k -= 4 {
					digit := byte((v >> uint(k)) & 0x0F)
					if digit < 10 {
						e.put(digit + '0')
					} else {
						e.put(digit + 'A' - 10)
					}
				}
			}
			spaces = false
		} else if yIsSpace(value, i) {
			if allowBreaks && !spaces && e.column > e.bestWidth && i > 0 && i < len(value)-1 {
				e.writeIndent()
				if yIsSpace(value, i+1) {
					e.put('\\')
				}
				i += yWidth(value[i])
			} else {
				e.write(value, &i)
			}
			spaces = true
		} else {
			e.write(value, &i)
			spaces = false
		}
	}
	e.writeIndicator("\"", false, false, false)
}

func (e *yemitter) writeBlockScalarHints(value []byte) {
	if yIsSpace(value, 0) || yIsBreak(value, 0) {
		e.writeIndicator(string(rune('0'+e.bestIndent)), false, false, false)
	}
	e.openEnded = false
	var chomp byte
	if len(value) == 0 {
		chomp = '-'
	} else {
		i := len(value) - 1
		for i > 0 && value[i]&0xC0 == 0x80 {
			i--
		}
		if !yIsBreak(value, i) {
			chomp = '-'
		} else if i == 0 {
			chomp = '+'
			e.openEnded = true
		} else {
			i--
			for i > 0 && value[i]&0xC0 == 0x80 {
				i--
			}
			if yIsBreak(value, i) {
				chomp = '+'
				e.openEnded = true
			}
		}
	}
	if chomp != 0 {
		e.writeIndicator(string(chomp), false, false, false)
	}
}

func (e *yemitter) writeLiteral(value []byte) {
	e.writeIndicator("|", true, false, false)
	e.writeBlockScalarHints(value)
	e.putBreak()
	e.indention = true
	e.whitespace = true
	breaks := true
	for i := 0; i < len(value); {
		if yIsBreak(value, i) {
			e.writeBreak(value, &i)
			e.indention = true
			breaks = true
		} else {
			if breaks {
				e.writeIndent()
			}
			e.write(value, &i)
			e.indention = false
			breaks = false
		}
	}
}

// emitScalar emits a scalar value with the requested style (after selection)
func (e *yemitter) emitScalar(value string, requested int, simpleKey bool) {
	v := []byte(value)
	a := analyzeScalar(v)
	style := requested
	if style == styleAny {
		style = stylePlain
	}
	if simpleKey && a.multiline {
		style = styleDouble
	}
	if style == stylePlain {
		if (e.flowLevel > 0 && !a.flowPlainAllowed) || (e.flowLevel == 0 && !a.blockPlainAllowed) {
			style = styleSingle
		}
		if len(v) == 0 && (e.flowLevel > 0 || simpleKey) {
			style = styleSingle
		}
	}
	if style == styleSingle {
		if !a.singleQuotedAllowed {
			style = styleDouble
		}
	}
	if style == styleLiteral {
		if !a.blockAllowed || e.flowLevel > 0 || simpleKey {
			style = styleDouble
		}
	}

	e.increaseIndent(true, false)
	allowBreaks := !simpleKey
	switch style {
	case stylePlain:
		e.writePlain(v, allowBreaks)
	case styleSingle:
		e.writeSingleQuoted(v, allowBreaks)
	case styleDouble:
		e.writeDoubleQuoted(v, allowBreaks)
	case styleLiteral:
		e.writeLiteral(v)
	}
	e.popIndent()
}

// stringStyle mirrors encoder.stringv in yaml.v2
func stringStyle(s string) (string, int) {
	canUsePlain := true
	if !utf8.ValidString(s) {
		// not expected for our data; fall back to double quoting
		return s, styleDouble
	}
	canUsePlain = resolveTag(s) == "str" && !isBase60Float(s)
	switch {
	case strings.Contains(s, "\n"):
		return s, styleLiteral
	case canUsePlain:
		return s, stylePlain
	default:
		return s, styleDouble
	}
}

// ---- higher level document building ----

type yNode struct {
	kind   int // 0 scalar string, 1 raw plain (time/bool), 2 seq of strings, 3 seq of maps
	str    string
	strs   []string
	maps   [][]yKV
}

type yKV struct {
	key string
	val yNode
}

func ystr(s string) yNode        { return yNode{kind: 0, str: s} }
func yraw(s string) yNode        { return yNode{kind: 1, str: s} }
func yseq(s []string) yNode      { return yNode{kind: 2, strs: s} }
func ymapseq(m [][]yKV) yNode    { return yNode{kind: 3, maps: m} }

func (e *yemitter) emitValue(n yNode) {
	switch n.kind {
	case 0:
		s, st := stringStyle(n.str)
		e.emitScalar(s, st, false)
	case 1:
		e.emitScalar(n.str, stylePlain, false)
	case 2:
		if len(n.strs) == 0 {
			e.emitEmptyFlowSeq()
			return
		}
		e.emitBlockSeq(len(n.strs), func(i int) {
			s, st := stringStyle(n.strs[i])
			e.emitScalar(s, st, false)
		})
	case 3:
		if len(n.maps) == 0 {
			e.emitEmptyFlowSeq()
			return
		}
		e.emitBlockSeq(len(n.maps), func(i int) {
			e.emitBlockMapping(n.maps[i])
		})
	}
}

func (e *yemitter) emitEmptyFlowSeq() {
	// flow sequence start
	e.writeIndicator("[", true, true, false)
	e.increaseIndent(true, false)
	e.flowLevel++
	// end
	e.flowLevel--
	e.popIndent()
	e.writeIndicator("]", false, false, false)
}

func (e *yemitter) emitBlockSeq(n int, item func(i int)) {
	e.increaseIndent(false, e.mappingCtx && !e.indention)
	for i := 0; i < n; i++ {
		e.writeIndent()
		e.writeIndicator("-", true, false, true)
		e.mappingCtx = false
		item(i)
	}
	e.popIndent()
}

func (e *yemitter) emitBlockMapping(kvs []yKV) {
	if len(kvs) == 0 {
		e.writeIndicator("{", true, true, false)
		e.writeIndicator("}", false, false, false)
		return
	}
	e.increaseIndent(false, false)
	for _, kv := range kvs {
		e.writeIndent()
		// simple key
		e.emitScalar(kv.key, stylePlain, true)
		e.writeIndicator(":", false, false, false)
		e.mappingCtx = true
		e.emitValue(kv.val)
		e.mappingCtx = false
	}
	e.popIndent()
}

func yamlMarshalDoc(kvs []yKV) []byte {
	e := newYEmitter()
	e.emitBlockMapping(kvs)
	// document end: ensure trailing newline
	if e.column != 0 || !e.indention {
		e.putBreak()
	}
	out := e.buf.Bytes()
	// a document always ends with exactly one newline after content
	if len(out) == 0 || out[len(out)-1] != '\n' {
		out = append(out, '\n')
	}
	return out
}
