package main

// A small YAML parser supporting the subset of YAML needed to read task
// files (block mappings/sequences, flow collections, all scalar styles).

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

const (
	ynScalar = iota
	ynSeq
	ynMap
)

type ynode struct {
	kind   int
	value  string
	quoted bool // single/double quoted or block scalar => always string
	isNull bool // explicit or implicit null (empty value)
	items  []*ynode
	keys   []*ynode
	vals   []*ynode
	line   int // 1-based
}

type yamlError struct {
	msg string
}

func (e *yamlError) Error() string { return e.msg }

func yfail(line int, format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	if line > 0 {
		panic(&yamlError{fmt.Sprintf("yaml: line %d: %s", line, msg)})
	}
	panic(&yamlError{"yaml: " + msg})
}

type yline struct {
	raw    string
	indent int // number of leading spaces
	text   string
	blank  bool // empty or comment-only
	num    int
}

type yparser struct {
	lines []yline
	pos   int
}

func yamlParse(data []byte) (root *ynode, err error) {
	defer func() {
		if r := recover(); r != nil {
			if ye, ok := r.(*yamlError); ok {
				err = ye
				root = nil
				return
			}
			panic(r)
		}
	}()
	s := string(data)
	if !utf8.ValidString(s) {
		return nil, &yamlError{"yaml: invalid leading UTF-8 octet"}
	}
	s = strings.TrimPrefix(s, "\ufeff")
	s = strings.ReplaceAll(s, "\r\n", "\n")
	rawLines := strings.Split(s, "\n")
	p := &yparser{}
	for i, l := range rawLines {
		ind := 0
		for ind < len(l) && l[ind] == ' ' {
			ind++
		}
		text := l[ind:]
		blank := strings.TrimSpace(text) == "" || strings.HasPrefix(strings.TrimLeft(text, " \t"), "#")
		p.lines = append(p.lines, yline{raw: l, indent: ind, text: text, blank: blank, num: i + 1})
	}
	// strip document markers
	for i := range p.lines {
		t := p.lines[i].raw
		if p.lines[i].indent == 0 && (t == "---" || strings.HasPrefix(t, "--- ") || t == "..." || strings.HasPrefix(t, "... ")) {
			rest := ""
			if strings.HasPrefix(t, "--- ") {
				rest = strings.TrimSpace(t[4:])
			}
			if rest == "" || strings.HasPrefix(rest, "#") {
				p.lines[i].blank = true
			} else {
				p.lines[i].text = rest
				p.lines[i].indent = 4
			}
		}
	}
	p.skipBlank()
	if p.pos >= len(p.lines) {
		return &ynode{kind: ynScalar, isNull: true}, nil
	}
	if strings.HasPrefix(p.lines[p.pos].text, "\t") {
		yfail(p.lines[p.pos].num, "found character that cannot start any token")
	}
	n := p.parseBlock(p.lines[p.pos].indent, -1)
	p.skipBlank()
	if p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.indent > 0 {
			yfail(l.num, "did not find expected key")
		}
		yfail(l.num, "did not find expected <document start>")
	}
	return n, nil
}

func (p *yparser) skipBlank() {
	for p.pos < len(p.lines) && p.lines[p.pos].blank {
		p.pos++
	}
}

// isSeqItem reports whether text starts a block sequence entry
func isSeqItem(text string) bool {
	return text == "-" || strings.HasPrefix(text, "- ") || strings.HasPrefix(text, "-\t")
}

// findMappingColon finds the position of a "key: " separator in text, or -1
func findMappingColon(text string) int {
	if text == "" {
		return -1
	}
	i := 0
	if text[0] == '"' || text[0] == '\'' {
		q := text[0]
		j := 1
		for j < len(text) {
			if q == '\'' && text[j] == '\'' {
				if j+1 < len(text) && text[j+1] == '\'' {
					j += 2
					continue
				}
				break
			}
			if q == '"' && text[j] == '\\' {
				j += 2
				continue
			}
			if q == '"' && text[j] == '"' {
				break
			}
			j++
		}
		if j >= len(text) {
			return -1
		}
		i = j + 1
		for i < len(text) && (text[i] == ' ' || text[i] == '\t') {
			i++
		}
		if i < len(text) && text[i] == ':' && (i+1 == len(text) || text[i+1] == ' ' || text[i+1] == '\t') {
			return i
		}
		return -1
	}
	switch text[0] {
	case '[', '{', '|', '>', '#', '&', '*', '!', '%', '@', '`':
		return -1
	}
	for i = 0; i < len(text); i++ {
		c := text[i]
		if c == '#' && i > 0 && (text[i-1] == ' ' || text[i-1] == '\t') {
			return -1
		}
		if c == ':' && (i+1 == len(text) || text[i+1] == ' ' || text[i+1] == '\t') {
			return i
		}
	}
	return -1
}

// parseBlock parses a block node whose first line is at p.pos with the given indentation.
// parentIndent is the indentation of the enclosing mapping (-1 at root).
func (p *yparser) parseBlock(indent int, parentIndent int) *ynode {
	l := p.lines[p.pos]
	if isSeqItem(l.text) {
		return p.parseSeq(l.indent)
	}
	if findMappingColon(l.text) >= 0 {
		return p.parseMap(l.indent)
	}
	// scalar starting on its own line
	return p.parseScalarAt(l.text, l.indent, parentIndent, l.num)
}

func (p *yparser) parseSeq(indent int) *ynode {
	n := &ynode{kind: ynSeq, line: p.lines[p.pos].num}
	for {
		p.skipBlank()
		if p.pos >= len(p.lines) {
			break
		}
		l := p.lines[p.pos]
		if l.indent < indent {
			break
		}
		if l.indent > indent {
			yfail(l.num, "did not find expected '-' indicator")
		}
		if !isSeqItem(l.text) {
			if findMappingColon(l.text) >= 0 {
				// end of indentless sequence inside mapping
				break
			}
			yfail(l.num, "did not find expected '-' indicator")
		}
		rest := strings.TrimLeft(l.text[1:], " \t")
		itemCol := indent + (len(l.text) - len(rest))
		if rest == "" || strings.HasPrefix(rest, "#") {
			// value on following lines
			p.pos++
			p.skipBlank()
			if p.pos < len(p.lines) && p.lines[p.pos].indent > indent {
				n.items = append(n.items, p.parseBlock(p.lines[p.pos].indent, indent))
			} else {
				n.items = append(n.items, &ynode{kind: ynScalar, isNull: true, line: l.num})
			}
			continue
		}
		// replace the current line by its content so nested parsing works
		p.lines[p.pos].indent = itemCol
		p.lines[p.pos].text = rest
		n.items = append(n.items, p.parseBlock(itemCol, indent))
	}
	return n
}

func (p *yparser) parseMap(indent int) *ynode {
	n := &ynode{kind: ynMap, line: p.lines[p.pos].num}
	for {
		p.skipBlank()
		if p.pos >= len(p.lines) {
			break
		}
		l := p.lines[p.pos]
		if l.indent < indent {
			break
		}
		if strings.HasPrefix(l.text, "\t") {
			yfail(l.num, "found character that cannot start any token")
		}
		if l.indent > indent {
			yfail(l.num, "mapping values are not allowed in this context")
		}
		ci := findMappingColon(l.text)
		if ci < 0 {
			if isSeqItem(l.text) {
				yfail(l.num, "did not find expected key")
			}
			// could be a multi-line key or garbage
			yfail(l.num+1, "could not find expected ':'")
		}
		keyText := strings.TrimRight(l.text[:ci], " \t")
		key := p.scalarFromInline(keyText, l.num)
		rest := strings.TrimLeft(l.text[ci+1:], " \t")
		var val *ynode
		if rest == "" || strings.HasPrefix(rest, "#") {
			p.pos++
			p.skipBlank()
			if p.pos < len(p.lines) {
				nl := p.lines[p.pos]
				if nl.indent > indent {
					val = p.parseBlock(nl.indent, indent)
				} else if nl.indent == indent && isSeqItem(nl.text) {
					val = p.parseSeq(indent)
				}
			}
			if val == nil {
				val = &ynode{kind: ynScalar, isNull: true, line: l.num}
			}
		} else {
			valCol := indent + (len(l.text) - len(rest))
			p.lines[p.pos].indent = valCol
			p.lines[p.pos].text = rest
			if isSeqItem(rest) {
				yfail(l.num, "block sequence entries are not allowed in this context")
			}
			if findMappingColon(rest) >= 0 && rest[0] != '"' && rest[0] != '\'' {
				yfail(l.num, "mapping values are not allowed in this context")
			}
			val = p.parseScalarAt(rest, valCol, indent, l.num)
		}
		n.keys = append(n.keys, key)
		n.vals = append(n.vals, val)
	}
	return n
}

func (p *yparser) scalarFromInline(text string, line int) *ynode {
	if text == "" {
		return &ynode{kind: ynScalar, isNull: true, line: line}
	}
	if text[0] == '"' {
		v, rest := parseDoubleQuoted(text[1:], line)
		if strings.TrimSpace(rest) != "" {
			yfail(line, "did not find expected key")
		}
		return &ynode{kind: ynScalar, value: v, quoted: true, line: line}
	}
	if text[0] == '\'' {
		v, rest := parseSingleQuoted(text[1:], line)
		if strings.TrimSpace(rest) != "" {
			yfail(line, "did not find expected key")
		}
		return &ynode{kind: ynScalar, value: v, quoted: true, line: line}
	}
	return plainNode(text, line)
}

func plainNode(v string, line int) *ynode {
	n := &ynode{kind: ynScalar, value: v, line: line}
	if resolveTag(v) == "null" {
		n.isNull = true
	}
	return n
}

// parseScalarAt parses a value starting at the current line (p.pos), whose
// text is given. parentIndent is the indentation of the enclosing block.
func (p *yparser) parseScalarAt(text string, col int, parentIndent int, line int) *ynode {
	switch text[0] {
	case '|', '>':
		return p.parseBlockScalar(text, parentIndent, line)
	case '[', '{':
		src := p.collectFlow(text)
		fp := &flowParser{s: src, line: line}
		n := fp.parseNode()
		fp.skipWS()
		if fp.i < len(fp.s) && fp.s[fp.i] != '#' {
			yfail(line, "did not find expected <document start>")
		}
		return n
	case '"', '\'':
		return p.parseQuotedMultiline(text, line)
	case '&', '*', '!', '%', '@', '`':
		if text[0] == '@' || text[0] == '`' {
			yfail(line, "found character that cannot start any token")
		}
	}
	if strings.HasPrefix(text, "- ") || text == "-" {
		yfail(line, "block sequence entries are not allowed in this context")
	}
	// plain scalar, possibly multi-line
	var parts []string
	first := stripComment(text)
	parts = append(parts, strings.TrimRight(first, " \t"))
	commented := first != text
	p.pos++
	emptyLines := 0
	for !commented && p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if strings.TrimSpace(l.text) == "" {
			emptyLines++
			p.pos++
			continue
		}
		if l.indent <= parentIndent || strings.HasPrefix(strings.TrimLeft(l.text, " \t"), "#") {
			break
		}
		t := strings.TrimLeft(l.text, " \t")
		if findMappingColon(t) >= 0 {
			yfail(l.num, "mapping values are not allowed in this context")
		}
		t2 := stripComment(t)
		if t2 != t {
			commented = true
		}
		t2 = strings.TrimRight(t2, " \t")
		if emptyLines > 0 {
			parts = append(parts, strings.Repeat("\n", emptyLines))
			parts = append(parts, t2)
		} else {
			parts = append(parts, " "+t2)
		}
		emptyLines = 0
		p.pos++
	}
	// back up over trailing empty lines so they are treated as blank
	if emptyLines > 0 {
		p.pos -= emptyLines
		for p.pos < len(p.lines) && strings.TrimSpace(p.lines[p.pos].text) == "" {
			p.pos++
		}
	}
	v := strings.Join(parts, "")
	return plainNode(v, line)
}

func stripComment(s string) string {
	for i := 0; i < len(s); i++ {
		if s[i] == '#' && i > 0 && (s[i-1] == ' ' || s[i-1] == '\t') {
			return s[:i]
		}
	}
	return s
}

func (p *yparser) collectFlow(text string) string {
	// gather lines until brackets are balanced
	var b strings.Builder
	b.WriteString(text)
	depth := 0
	inS, inD := false, false
	count := func(s string) {
		for i := 0; i < len(s); i++ {
			c := s[i]
			switch {
			case inD:
				if c == '\\' {
					i++
				} else if c == '"' {
					inD = false
				}
			case inS:
				if c == '\'' {
					if i+1 < len(s) && s[i+1] == '\'' {
						i++
					} else {
						inS = false
					}
				}
			case c == '"':
				inD = true
			case c == '\'':
				inS = true
			case c == '[' || c == '{':
				depth++
			case c == ']' || c == '}':
				depth--
			case c == '#' && i > 0 && (s[i-1] == ' ' || s[i-1] == '\t'):
				return
			}
		}
	}
	count(text)
	startLine := p.lines[p.pos].num
	p.pos++
	for depth > 0 {
		if p.pos >= len(p.lines) {
			_ = startLine
			yfail(0, "line %d: did not find expected ',' or ']'", startLine)
		}
		l := p.lines[p.pos]
		b.WriteString(" ")
		b.WriteString(strings.TrimLeft(l.text, " \t"))
		count(l.text)
		p.pos++
	}
	return b.String()
}

func (p *yparser) parseQuotedMultiline(text string, line int) *ynode {
	q := text[0]
	src := text[1:]
	for {
		var v, rest string
		ok := func() (ok bool) {
			defer func() {
				if r := recover(); r != nil {
					if _, is := r.(*yamlError); is && p.pos+1 < len(p.lines) {
						ok = false
						return
					}
					panic(r)
				}
			}()
			if q == '"' {
				v, rest = parseDoubleQuoted(src, line)
			} else {
				v, rest = parseSingleQuoted(src, line)
			}
			return true
		}()
		if ok {
			r := strings.TrimSpace(rest)
			if r != "" && !strings.HasPrefix(r, "#") {
				yfail(line, "did not find expected key")
			}
			p.pos++
			return &ynode{kind: ynScalar, value: v, quoted: true, line: line}
		}
		p.pos++
		src += "\n" + p.lines[p.pos].raw
	}
}

// fold quoted-scalar line breaks per YAML rules
func foldQuotedLines(s string) string {
	if !strings.Contains(s, "\n") {
		return s
	}
	lines := strings.Split(s, "\n")
	var b strings.Builder
	for i, l := range lines {
		if i > 0 {
			l = strings.TrimLeft(l, " \t")
		}
		if i < len(lines)-1 {
			l = strings.TrimRight(l, " \t")
		}
		lines[i] = l
	}
	b.WriteString(lines[0])
	empties := 0
	for i := 1; i < len(lines); i++ {
		if lines[i] == "" && i < len(lines)-1 {
			empties++
			continue
		}
		if empties > 0 {
			b.WriteString(strings.Repeat("\n", empties))
		} else {
			b.WriteString(" ")
		}
		empties = 0
		b.WriteString(lines[i])
	}
	return b.String()
}

func parseSingleQuoted(s string, line int) (string, string) {
	var b strings.Builder
	i := 0
	for {
		if i >= len(s) {
			yfail(0, "line %d: found unexpected end of stream", line)
		}
		c := s[i]
		if c == '\'' {
			if i+1 < len(s) && s[i+1] == '\'' {
				b.WriteByte('\'')
				i += 2
				continue
			}
			return foldQuotedLines(b.String()), s[i+1:]
		}
		b.WriteByte(c)
		i++
	}
}

func parseDoubleQuoted(s string, line int) (string, string) {
	// first split raw content to handle folding, then unescape
	var segs []string
	var cur strings.Builder
	i := 0
	for {
		if i >= len(s) {
			yfail(0, "line %d: found unexpected end of stream", line)
		}
		c := s[i]
		if c == '"' {
			break
		}
		if c == '\\' && i+1 < len(s) && s[i+1] == '\n' {
			// escaped line break: join without space
			segs = append(segs, cur.String()+"\x00ESCNL")
			cur.Reset()
			i += 2
			continue
		}
		if c == '\\' && i+1 < len(s) {
			cur.WriteByte(c)
			cur.WriteByte(s[i+1])
			i += 2
			continue
		}
		cur.WriteByte(c)
		i++
	}
	segs = append(segs, cur.String())
	rest := s[i+1:]
	// join segments
	var raw strings.Builder
	for k, sg := range segs {
		if strings.HasSuffix(sg, "\x00ESCNL") {
			raw.WriteString(strings.TrimSuffix(sg, "\x00ESCNL"))
			// next segment's leading whitespace stripped
			if k+1 < len(segs) {
				segs[k+1] = strings.TrimLeft(segs[k+1], " \t")
			}
			continue
		}
		raw.WriteString(sg)
	}
	folded := foldQuotedLinesDQ(raw.String())
	return unescapeDQ(folded, line), rest
}

func foldQuotedLinesDQ(s string) string {
	if !strings.Contains(s, "\n") {
		return s
	}
	// trailing whitespace before a raw newline is removed unless escaped
	lines := strings.Split(s, "\n")
	for i := range lines {
		if i > 0 {
			lines[i] = strings.TrimLeft(lines[i], " \t")
		}
		if i < len(lines)-1 {
			l := lines[i]
			trimmed := strings.TrimRight(l, " \t")
			// keep escaped trailing space
			if strings.HasSuffix(trimmed, "\\") && len(trimmed) < len(l) {
				trimmed = trimmed + l[len(trimmed):len(trimmed)+1]
			}
			lines[i] = trimmed
		}
	}
	var b strings.Builder
	b.WriteString(lines[0])
	empties := 0
	for i := 1; i < len(lines); i++ {
		if lines[i] == "" && i < len(lines)-1 {
			empties++
			continue
		}
		if empties > 0 {
			b.WriteString(strings.Repeat("\n", empties))
		} else {
			b.WriteString(" ")
		}
		empties = 0
		b.WriteString(lines[i])
	}
	return b.String()
}

func unescapeDQ(s string, line int) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != '\\' || i+1 >= len(s) {
			b.WriteByte(c)
			continue
		}
		i++
		switch s[i] {
		case '0':
			b.WriteByte(0)
		case 'a':
			b.WriteByte(7)
		case 'b':
			b.WriteByte(8)
		case 't', '\t':
			b.WriteByte(9)
		case 'n':
			b.WriteByte('\n')
		case 'v':
			b.WriteByte(0x0b)
		case 'f':
			b.WriteByte(0x0c)
		case 'r':
			b.WriteByte('\r')
		case 'e':
			b.WriteByte(0x1b)
		case ' ':
			b.WriteByte(' ')
		case '"':
			b.WriteByte('"')
		case '/':
			b.WriteByte('/')
		case '\\':
			b.WriteByte('\\')
		case 'N':
			b.WriteString("\u0085")
		case '_':
			b.WriteString("\u00a0")
		case 'L':
			b.WriteString("\u2028")
		case 'P':
			b.WriteString("\u2029")
		case 'x', 'u', 'U':
			n := map[byte]int{'x': 2, 'u': 4, 'U': 8}[s[i]]
			if i+n >= len(s)+0 && i+n > len(s)-1+1 {
				yfail(line, "did not find expected hexdecimal number")
			}
			hex := s[i+1 : min(len(s), i+1+n)]
			v, err := strconv.ParseUint(hex, 16, 32)
			if err != nil || len(hex) != n {
				yfail(line, "did not find expected hexdecimal number")
			}
			b.WriteRune(rune(v))
			i += n
		default:
			yfail(line, "found unknown escape character while parsing a quoted scalar")
		}
	}
	return b.String()
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func (p *yparser) parseBlockScalar(header string, parentIndent int, line int) *ynode {
	literal := header[0] == '|'
	chomp := byte(0)
	explicitIndent := 0
	h := stripComment(header[1:])
	h = strings.TrimSpace(h)
	for _, c := range []byte(h) {
		switch {
		case c == '-' || c == '+':
			chomp = c
		case c >= '1' && c <= '9':
			explicitIndent = int(c - '0')
		default:
			yfail(line, "did not find expected comment or line break")
		}
	}
	p.pos++
	// determine content indentation
	baseIndent := parentIndent
	if baseIndent < 0 {
		baseIndent = 0
	}
	contentIndent := -1
	if explicitIndent > 0 {
		contentIndent = baseIndent + explicitIndent
		if parentIndent < 0 {
			contentIndent = explicitIndent
		}
	}
	var lines []string
	start := p.pos
	if contentIndent < 0 {
		for j := start; j < len(p.lines); j++ {
			if strings.TrimSpace(p.lines[j].raw) == "" {
				continue
			}
			contentIndent = p.lines[j].indent
			break
		}
		if contentIndent <= parentIndent {
			contentIndent = parentIndent + 1
		}
	}
	for p.pos < len(p.lines) {
		raw := p.lines[p.pos].raw
		if strings.TrimSpace(raw) == "" {
			if len(raw) > contentIndent {
				lines = append(lines, raw[contentIndent:])
			} else {
				lines = append(lines, "")
			}
			p.pos++
			continue
		}
		if p.lines[p.pos].indent < contentIndent {
			break
		}
		lines = append(lines, raw[contentIndent:])
		p.pos++
	}
	// trailing blank lines
	trailing := 0
	for len(lines) > 0 && strings.TrimSpace(lines[len(lines)-1]) == "" && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
		trailing++
	}
	// the final "line" of the file after the last newline is not a real line
	if p.pos >= len(p.lines) && trailing > 0 && p.lines[len(p.lines)-1].raw == "" {
		trailing--
	}
	// back up so that blank lines after the scalar are skipped by caller
	var body string
	if literal {
		body = strings.Join(lines, "\n")
	} else {
		body = foldBlock(lines)
	}
	if len(lines) == 0 {
		body = ""
		switch chomp {
		case '+':
			return &ynode{kind: ynScalar, value: strings.Repeat("\n", trailing), quoted: true, line: line}
		default:
			return &ynode{kind: ynScalar, value: "", quoted: true, line: line}
		}
	}
	switch chomp {
	case '-':
	case '+':
		body += "\n" + strings.Repeat("\n", trailing)
	default:
		body += "\n"
	}
	return &ynode{kind: ynScalar, value: body, quoted: true, line: line}
}

func foldBlock(lines []string) string {
	var b strings.Builder
	prevMoreIndented := false
	for i, l := range lines {
		more := strings.HasPrefix(l, " ") || strings.HasPrefix(l, "\t")
		if i > 0 {
			if l == "" {
				b.WriteString("\n")
				continue
			}
			prev := lines[i-1]
			if prev == "" {
				// already wrote newline(s) for empty lines
				if more || prevMoreIndented {
					b.WriteString("\n")
				}
			} else if more || prevMoreIndented {
				b.WriteString("\n")
			} else {
				b.WriteString(" ")
			}
		}
		b.WriteString(l)
		prevMoreIndented = more
	}
	return b.String()
}

// ---- flow parser ----

type flowParser struct {
	s    string
	i    int
	line int
}

func (f *flowParser) skipWS() {
	for f.i < len(f.s) && (f.s[f.i] == ' ' || f.s[f.i] == '\t' || f.s[f.i] == '\n') {
		f.i++
	}
}

func (f *flowParser) parseNode() *ynode {
	f.skipWS()
	if f.i >= len(f.s) {
		yfail(f.line, "did not find expected node content")
	}
	switch f.s[f.i] {
	case '[':
		f.i++
		n := &ynode{kind: ynSeq, line: f.line}
		for {
			f.skipWS()
			if f.i >= len(f.s) {
				yfail(f.line, "did not find expected ',' or ']'")
			}
			if f.s[f.i] == ']' {
				f.i++
				return n
			}
			item := f.parseNode()
			f.skipWS()
			// "a: b" single pair mapping inside sequence
			if f.i < len(f.s) && f.s[f.i] == ':' {
				f.i++
				v := f.parseNode()
				item = &ynode{kind: ynMap, keys: []*ynode{item}, vals: []*ynode{v}, line: f.line}
				f.skipWS()
			}
			n.items = append(n.items, item)
			if f.i >= len(f.s) {
				yfail(f.line, "did not find expected ',' or ']'")
			}
			if f.s[f.i] == ',' {
				f.i++
				continue
			}
			if f.s[f.i] == ']' {
				f.i++
				return n
			}
			yfail(f.line, "did not find expected ',' or ']'")
		}
	case '{':
		f.i++
		n := &ynode{kind: ynMap, line: f.line}
		for {
			f.skipWS()
			if f.i >= len(f.s) {
				yfail(f.line, "did not find expected ',' or '}'")
			}
			if f.s[f.i] == '}' {
				f.i++
				return n
			}
			k := f.parseNode()
			f.skipWS()
			var v *ynode
			if f.i < len(f.s) && f.s[f.i] == ':' {
				f.i++
				f.skipWS()
				if f.i < len(f.s) && (f.s[f.i] == ',' || f.s[f.i] == '}') {
					v = &ynode{kind: ynScalar, isNull: true, line: f.line}
				} else {
					v = f.parseNode()
				}
			} else {
				v = &ynode{kind: ynScalar, isNull: true, line: f.line}
			}
			n.keys = append(n.keys, k)
			n.vals = append(n.vals, v)
			f.skipWS()
			if f.i >= len(f.s) {
				yfail(f.line, "did not find expected ',' or '}'")
			}
			if f.s[f.i] == ',' {
				f.i++
				continue
			}
			if f.s[f.i] == '}' {
				f.i++
				return n
			}
			yfail(f.line, "did not find expected ',' or '}'")
		}
	case '"':
		v, rest := parseDoubleQuoted(f.s[f.i+1:], f.line)
		f.i = len(f.s) - len(rest)
		return &ynode{kind: ynScalar, value: v, quoted: true, line: f.line}
	case '\'':
		v, rest := parseSingleQuoted(f.s[f.i+1:], f.line)
		f.i = len(f.s) - len(rest)
		return &ynode{kind: ynScalar, value: v, quoted: true, line: f.line}
	case ',', ']', '}':
		return &ynode{kind: ynScalar, isNull: true, line: f.line}
	}
	// plain scalar in flow context
	start := f.i
	for f.i < len(f.s) {
		c := f.s[f.i]
		if c == ',' || c == ']' || c == '}' || c == '[' || c == '{' {
			break
		}
		if c == ':' && (f.i+1 >= len(f.s) || f.s[f.i+1] == ' ' || f.s[f.i+1] == ',' || f.s[f.i+1] == ']' || f.s[f.i+1] == '}') {
			break
		}
		if c == '#' && f.i > start && (f.s[f.i-1] == ' ' || f.s[f.i-1] == '\t') {
			break
		}
		f.i++
	}
	v := strings.TrimSpace(f.s[start:f.i])
	v = strings.Join(strings.Fields(v), " ")
	return plainNode(v, f.line)
}
EOF
go vet . 2>&1 | head"}

actions.command:
cd /workspace; cat > yamlparse.go <<'EOF'
package main

// A small YAML parser supporting the subset of YAML needed to read task
// files (block mappings/sequences, flow collections, all scalar styles).

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

const (
	ynScalar = iota
	ynSeq
	ynMap
)

type ynode struct {
	kind   int
	value  string
	quoted bool // single/double quoted or block scalar => always string
	isNull bool // explicit or implicit null (empty value)
	items  []*ynode
	keys   []*ynode
	vals   []*ynode
	line   int // 1-based
}

type yamlError struct {
	msg string
}

func (e *yamlError) Error() string { return e.msg }

func yfail(line int, format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	if line > 0 {
		panic(&yamlError{fmt.Sprintf("yaml: line %d: %s", line, msg)})
	}
	panic(&yamlError{"yaml: " + msg})
}

type yline struct {
	raw    string
	indent int // number of leading spaces
	text   string
	blank  bool // empty or comment-only
	num    int
}

type yparser struct {
	lines []yline
	pos   int
}

func yamlParse(data []byte) (root *ynode, err error) {
	defer func() {
		if r := recover(); r != nil {
			if ye, ok := r.(*yamlError); ok {
				err = ye
				root = nil
				return
			}
			panic(r)
		}
	}()
	s := string(data)
	if !utf8.ValidString(s) {
		return nil, &yamlError{"yaml: invalid leading UTF-8 octet"}
	}
	s = strings.TrimPrefix(s, "\ufeff")
	s = strings.ReplaceAll(s, "\r\n", "\n")
	rawLines := strings.Split(s, "\n")
	p := &yparser{}
	for i, l := range rawLines {
		ind := 0
		for ind < len(l) && l[ind] == ' ' {
			ind++
		}
		text := l[ind:]
		blank := strings.TrimSpace(text) == "" || strings.HasPrefix(strings.TrimLeft(text, " \t"), "#")
		p.lines = append(p.lines, yline{raw: l, indent: ind, text: text, blank: blank, num: i + 1})
	}
	// strip document markers
	for i := range p.lines {
		t := p.lines[i].raw
		if p.lines[i].indent == 0 && (t == "---" || strings.HasPrefix(t, "--- ") || t == "..." || strings.HasPrefix(t, "... ")) {
			rest := ""
			if strings.HasPrefix(t, "--- ") {
				rest = strings.TrimSpace(t[4:])
			}
			if rest == "" || strings.HasPrefix(rest, "#") {
				p.lines[i].blank = true
			} else {
				p.lines[i].text = rest
				p.lines[i].indent = 4
			}
		}
	}
	p.skipBlank()
	if p.pos >= len(p.lines) {
		return &ynode{kind: ynScalar, isNull: true}, nil
	}
	if strings.HasPrefix(p.lines[p.pos].text, "\t") {
		yfail(p.lines[p.pos].num, "found character that cannot start any token")
	}
	n := p.parseBlock(p.lines[p.pos].indent, -1)
	p.skipBlank()
	if p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.indent > 0 {
			yfail(l.num, "did not find expected key")
		}
		yfail(l.num, "did not find expected <document start>")
	}
	return n, nil
}

func (p *yparser) skipBlank() {
	for p.pos < len(p.lines) && p.lines[p.pos].blank {
		p.pos++
	}
}

// isSeqItem reports whether text starts a block sequence entry
func isSeqItem(text string) bool {
	return text == "-" || strings.HasPrefix(text, "- ") || strings.HasPrefix(text, "-\t")
}

// findMappingColon finds the position of a "key: " separator in text, or -1
func findMappingColon(text string) int {
	if text == "" {
		return -1
	}
	i := 0
	if text[0] == '"' || text[0] == '\'' {
		q := text[0]
		j := 1
		for j < len(text) {
			if q == '\'' && text[j] == '\'' {
				if j+1 < len(text) && text[j+1] == '\'' {
					j += 2
					continue
				}
				break
			}
			if q == '"' && text[j] == '\\' {
				j += 2
				continue
			}
			if q == '"' && text[j] == '"' {
				break
			}
			j++
		}
		if j >= len(text) {
			return -1
		}
		i = j + 1
		for i < len(text) && (text[i] == ' ' || text[i] == '\t') {
			i++
		}
		if i < len(text) && text[i] == ':' && (i+1 == len(text) || text[i+1] == ' ' || text[i+1] == '\t') {
			return i
		}
		return -1
	}
	switch text[0] {
	case '[', '{', '|', '>', '#', '&', '*', '!', '%', '@', '`':
		return -1
	}
	for i = 0; i < len(text); i++ {
		c := text[i]
		if c == '#' && i > 0 && (text[i-1] == ' ' || text[i-1] == '\t') {
			return -1
		}
		if c == ':' && (i+1 == len(text) || text[i+1] == ' ' || text[i+1] == '\t') {
			return i
		}
	}
	return -1
}

// parseBlock parses a block node whose first line is at p.pos with the given indentation.
// parentIndent is the indentation of the enclosing mapping (-1 at root).
func (p *yparser) parseBlock(indent int, parentIndent int) *ynode {
	l := p.lines[p.pos]
	if isSeqItem(l.text) {
		return p.parseSeq(l.indent)
	}
	if findMappingColon(l.text) >= 0 {
		return p.parseMap(l.indent)
	}
	// scalar starting on its own line
	return p.parseScalarAt(l.text, l.indent, parentIndent, l.num)
}

func (p *yparser) parseSeq(indent int) *ynode {
	n := &ynode{kind: ynSeq, line: p.lines[p.pos].num}
	for {
		p.skipBlank()
		if p.pos >= len(p.lines) {
			break
		}
		l := p.lines[p.pos]
		if l.indent < indent {
			break
		}
		if l.indent > indent {
			yfail(l.num, "did not find expected '-' indicator")
		}
		if !isSeqItem(l.text) {
			if findMappingColon(l.text) >= 0 {
				// end of indentless sequence inside mapping
				break
			}
			yfail(l.num, "did not find expected '-' indicator")
		}
		rest := strings.TrimLeft(l.text[1:], " \t")
		itemCol := indent + (len(l.text) - len(rest))
		if rest == "" || strings.HasPrefix(rest, "#") {
			// value on following lines
			p.pos++
			p.skipBlank()
			if p.pos < len(p.lines) && p.lines[p.pos].indent > indent {
				n.items = append(n.items, p.parseBlock(p.lines[p.pos].indent, indent))
			} else {
				n.items = append(n.items, &ynode{kind: ynScalar, isNull: true, line: l.num})
			}
			continue
		}
		// replace the current line by its content so nested parsing works
		p.lines[p.pos].indent = itemCol
		p.lines[p.pos].text = rest
		n.items = append(n.items, p.parseBlock(itemCol, indent))
	}
	return n
}

func (p *yparser) parseMap(indent int) *ynode {
	n := &ynode{kind: ynMap, line: p.lines[p.pos].num}
	for {
		p.skipBlank()
		if p.pos >= len(p.lines) {
			break
		}
		l := p.lines[p.pos]
		if l.indent < indent {
			break
		}
		if strings.HasPrefix(l.text, "\t") {
			yfail(l.num, "found character that cannot start any token")
		}
		if l.indent > indent {
			yfail(l.num, "mapping values are not allowed in this context")
		}
		ci := findMappingColon(l.text)
		if ci < 0 {
			if isSeqItem(l.text) {
				yfail(l.num, "did not find expected key")
			}
			// could be a multi-line key or garbage
			yfail(l.num+1, "could not find expected ':'")
		}
		keyText := strings.TrimRight(l.text[:ci], " \t")
		key := p.scalarFromInline(keyText, l.num)
		rest := strings.TrimLeft(l.text[ci+1:], " \t")
		var val *ynode
		if rest == "" || strings.HasPrefix(rest, "#") {
			p.pos++
			p.skipBlank()
			if p.pos < len(p.lines) {
				nl := p.lines[p.pos]
				if nl.indent > indent {
					val = p.parseBlock(nl.indent, indent)
				} else if nl.indent == indent && isSeqItem(nl.text) {
					val = p.parseSeq(indent)
				}
			}
			if val == nil {
				val = &ynode{kind: ynScalar, isNull: true, line: l.num}
			}
		} else {
			valCol := indent + (len(l.text) - len(rest))
			p.lines[p.pos].indent = valCol
			p.lines[p.pos].text = rest
			if isSeqItem(rest) {
				yfail(l.num, "block sequence entries are not allowed in this context")
			}
			if findMappingColon(rest) >= 0 && rest[0] != '"' && rest[0] != '\'' {
				yfail(l.num, "mapping values are not allowed in this context")
			}
			val = p.parseScalarAt(rest, valCol, indent, l.num)
		}
		n.keys = append(n.keys, key)
		n.vals = append(n.vals, val)
	}
	return n
}

func (p *yparser) scalarFromInline(text string, line int) *ynode {
	if text == "" {
		return &ynode{kind: ynScalar, isNull: true, line: line}
	}
	if text[0] == '"' {
		v, rest := parseDoubleQuoted(text[1:], line)
		if strings.TrimSpace(rest) != "" {
			yfail(line, "did not find expected key")
		}
		return &ynode{kind: ynScalar, value: v, quoted: true, line: line}
	}
	if text[0] == '\'' {
		v, rest := parseSingleQuoted(text[1:], line)
		if strings.TrimSpace(rest) != "" {
			yfail(line, "did not find expected key")
		}
		return &ynode{kind: ynScalar, value: v, quoted: true, line: line}
	}
	return plainNode(text, line)
}

func plainNode(v string, line int) *ynode {
	n := &ynode{kind: ynScalar, value: v, line: line}
	if resolveTag(v) == "null" {
		n.isNull = true
	}
	return n
}

// parseScalarAt parses a value starting at the current line (p.pos), whose
// text is given. parentIndent is the indentation of the enclosing block.
func (p *yparser) parseScalarAt(text string, col int, parentIndent int, line int) *ynode {
	switch text[0] {
	case '|', '>':
		return p.parseBlockScalar(text, parentIndent, line)
	case '[', '{':
		src := p.collectFlow(text)
		fp := &flowParser{s: src, line: line}
		n := fp.parseNode()
		fp.skipWS()
		if fp.i < len(fp.s) && fp.s[fp.i] != '#' {
			yfail(line, "did not find expected <document start>")
		}
		return n
	case '"', '\'':
		return p.parseQuotedMultiline(text, line)
	case '&', '*', '!', '%', '@', '`':
		if text[0] == '@' || text[0] == '`' {
			yfail(line, "found character that cannot start any token")
		}
	}
	if strings.HasPrefix(text, "- ") || text == "-" {
		yfail(line, "block sequence entries are not allowed in this context")
	}
	// plain scalar, possibly multi-line
	var parts []string
	first := stripComment(text)
	parts = append(parts, strings.TrimRight(first, " \t"))
	commented := first != text
	p.pos++
	emptyLines := 0
	for !commented && p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if strings.TrimSpace(l.text) == "" {
			emptyLines++
			p.pos++
			continue
		}
		if l.indent <= parentIndent || strings.HasPrefix(strings.TrimLeft(l.text, " \t"), "#") {
			break
		}
		t := strings.TrimLeft(l.text, " \t")
		if findMappingColon(t) >= 0 {
			yfail(l.num, "mapping values are not allowed in this context")
		}
		t2 := stripComment(t)
		if t2 != t {
			commented = true
		}
		t2 = strings.TrimRight(t2, " \t")
		if emptyLines > 0 {
			parts = append(parts, strings.Repeat("\n", emptyLines))
			parts = append(parts, t2)
		} else {
			parts = append(parts, " "+t2)
		}
		emptyLines = 0
		p.pos++
	}
	// back up over trailing empty lines so they are treated as blank
	if emptyLines > 0 {
		p.pos -= emptyLines
		for p.pos < len(p.lines) && strings.TrimSpace(p.lines[p.pos].text) == "" {
			p.pos++
		}
	}
	v := strings.Join(parts, "")
	return plainNode(v, line)
}

func stripComment(s string) string {
	for i := 0; i < len(s); i++ {
		if s[i] == '#' && i > 0 && (s[i-1] == ' ' || s[i-1] == '\t') {
			return s[:i]
		}
	}
	return s
}

func (p *yparser) collectFlow(text string) string {
	// gather lines until brackets are balanced
	var b strings.Builder
	b.WriteString(text)
	depth := 0
	inS, inD := false, false
	count := func(s string) {
		for i := 0; i < len(s); i++ {
			c := s[i]
			switch {
			case inD:
				if c == '\\' {
					i++
				} else if c == '"' {
					inD = false
				}
			case inS:
				if c == '\'' {
					if i+1 < len(s) && s[i+1] == '\'' {
						i++
					} else {
						inS = false
					}
				}
			case c == '"':
				inD = true
			case c == '\'':
				inS = true
			case c == '[' || c == '{':
				depth++
			case c == ']' || c == '}':
				depth--
			case c == '#' && i > 0 && (s[i-1] == ' ' || s[i-1] == '\t'):
				return
			}
		}
	}
	count(text)
	startLine := p.lines[p.pos].num
	p.pos++
	for depth > 0 {
		if p.pos >= len(p.lines) {
			_ = startLine
			yfail(0, "line %d: did not find expected ',' or ']'", startLine)
		}
		l := p.lines[p.pos]
		b.WriteString(" ")
		b.WriteString(strings.TrimLeft(l.text, " \t"))
		count(l.text)
		p.pos++
	}
	return b.String()
}

func (p *yparser) parseQuotedMultiline(text string, line int) *ynode {
	q := text[0]
	src := text[1:]
	for {
		var v, rest string
		ok := func() (ok bool) {
			defer func() {
				if r := recover(); r != nil {
					if _, is := r.(*yamlError); is && p.pos+1 < len(p.lines) {
						ok = false
						return
					}
					panic(r)
				}
			}()
			if q == '"' {
				v, rest = parseDoubleQuoted(src, line)
			} else {
				v, rest = parseSingleQuoted(src, line)
			}
			return true
		}()
		if ok {
			r := strings.TrimSpace(rest)
			if r != "" && !strings.HasPrefix(r, "#") {
				yfail(line, "did not find expected key")
			}
			p.pos++
			return &ynode{kind: ynScalar, value: v, quoted: true, line: line}
		}
		p.pos++
		src += "\n" + p.lines[p.pos].raw
	}
}

// fold quoted-scalar line breaks per YAML rules
func foldQuotedLines(s string) string {
	if !strings.Contains(s, "\n") {
		return s
	}
	lines := strings.Split(s, "\n")
	var b strings.Builder
	for i, l := range lines {
		if i > 0 {
			l = strings.TrimLeft(l, " \t")
		}
		if i < len(lines)-1 {
			l = strings.TrimRight(l, " \t")
		}
		lines[i] = l
	}
	b.WriteString(lines[0])
	empties := 0
	for i := 1; i < len(lines); i++ {
		if lines[i] == "" && i < len(lines)-1 {
			empties++
			continue
		}
		if empties > 0 {
			b.WriteString(strings.Repeat("\n", empties))
		} else {
			b.WriteString(" ")
		}
		empties = 0
		b.WriteString(lines[i])
	}
	return b.String()
}

func parseSingleQuoted(s string, line int) (string, string) {
	var b strings.Builder
	i := 0
	for {
		if i >= len(s) {
			yfail(0, "line %d: found unexpected end of stream", line)
		}
		c := s[i]
		if c == '\'' {
			if i+1 < len(s) && s[i+1] == '\'' {
				b.WriteByte('\'')
				i += 2
				continue
			}
			return foldQuotedLines(b.String()), s[i+1:]
		}
		b.WriteByte(c)
		i++
	}
}

func parseDoubleQuoted(s string, line int) (string, string) {
	// first split raw content to handle folding, then unescape
	var segs []string
	var cur strings.Builder
	i := 0
	for {
		if i >= len(s) {
			yfail(0, "line %d: found unexpected end of stream", line)
		}
		c := s[i]
		if c == '"' {
			break
		}
		if c == '\\' && i+1 < len(s) && s[i+1] == '\n' {
			// escaped line break: join without space
			segs = append(segs, cur.String()+"\x00ESCNL")
			cur.Reset()
			i += 2
			continue
		}
		if c == '\\' && i+1 < len(s) {
			cur.WriteByte(c)
			cur.WriteByte(s[i+1])
			i += 2
			continue
		}
		cur.WriteByte(c)
		i++
	}
	segs = append(segs, cur.String())
	rest := s[i+1:]
	// join segments
	var raw strings.Builder
	for k, sg := range segs {
		if strings.HasSuffix(sg, "\x00ESCNL") {
			raw.WriteString(strings.TrimSuffix(sg, "\x00ESCNL"))
			// next segment's leading whitespace stripped
			if k+1 < len(segs) {
				segs[k+1] = strings.TrimLeft(segs[k+1], " \t")
			}
			continue
		}
		raw.WriteString(sg)
	}
	folded := foldQuotedLinesDQ(raw.String())
	return unescapeDQ(folded, line), rest
}

func foldQuotedLinesDQ(s string) string {
	if !strings.Contains(s, "\n") {
		return s
	}
	// trailing whitespace before a raw newline is removed unless escaped
	lines := strings.Split(s, "\n")
	for i := range lines {
		if i > 0 {
			lines[i] = strings.TrimLeft(lines[i], " \t")
		}
		if i < len(lines)-1 {
			l := lines[i]
			trimmed := strings.TrimRight(l, " \t")
			// keep escaped trailing space
			if strings.HasSuffix(trimmed, "\\") && len(trimmed) < len(l) {
				trimmed = trimmed + l[len(trimmed):len(trimmed)+1]
			}
			lines[i] = trimmed
		}
	}
	var b strings.Builder
	b.WriteString(lines[0])
	empties := 0
	for i := 1; i < len(lines); i++ {
		if lines[i] == "" && i < len(lines)-1 {
			empties++
			continue
		}
		if empties > 0 {
			b.WriteString(strings.Repeat("\n", empties))
		} else {
			b.WriteString(" ")
		}
		empties = 0
		b.WriteString(lines[i])
	}
	return b.String()
}

func unescapeDQ(s string, line int) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != '\\' || i+1 >= len(s) {
			b.WriteByte(c)
			continue
		}
		i++
		switch s[i] {
		case '0':
			b.WriteByte(0)
		case 'a':
			b.WriteByte(7)
		case 'b':
			b.WriteByte(8)
		case 't', '\t':
			b.WriteByte(9)
		case 'n':
			b.WriteByte('\n')
		case 'v':
			b.WriteByte(0x0b)
		case 'f':
			b.WriteByte(0x0c)
		case 'r':
			b.WriteByte('\r')
		case 'e':
			b.WriteByte(0x1b)
		case ' ':
			b.WriteByte(' ')
		case '"':
			b.WriteByte('"')
		case '/':
			b.WriteByte('/')
		case '\\':
			b.WriteByte('\\')
		case 'N':
			b.WriteString("\u0085")
		case '_':
			b.WriteString("\u00a0")
		case 'L':
			b.WriteString("\u2028")
		case 'P':
			b.WriteString("\u2029")
		case 'x', 'u', 'U':
			n := map[byte]int{'x': 2, 'u': 4, 'U': 8}[s[i]]
			if i+n >= len(s)+0 && i+n > len(s)-1+1 {
				yfail(line, "did not find expected hexdecimal number")
			}
			hex := s[i+1 : min(len(s), i+1+n)]
			v, err := strconv.ParseUint(hex, 16, 32)
			if err != nil || len(hex) != n {
				yfail(line, "did not find expected hexdecimal number")
			}
			b.WriteRune(rune(v))
			i += n
		default:
			yfail(line, "found unknown escape character while parsing a quoted scalar")
		}
	}
	return b.String()
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func (p *yparser) parseBlockScalar(header string, parentIndent int, line int) *ynode {
	literal := header[0] == '|'
	chomp := byte(0)
	explicitIndent := 0
	h := stripComment(header[1:])
	h = strings.TrimSpace(h)
	for _, c := range []byte(h) {
		switch {
		case c == '-' || c == '+':
			chomp = c
		case c >= '1' && c <= '9':
			explicitIndent = int(c - '0')
		default:
			yfail(line, "did not find expected comment or line break")
		}
	}
	p.pos++
	// determine content indentation
	baseIndent := parentIndent
	if baseIndent < 0 {
		baseIndent = 0
	}
	contentIndent := -1
	if explicitIndent > 0 {
		contentIndent = baseIndent + explicitIndent
		if parentIndent < 0 {
			contentIndent = explicitIndent
		}
	}
	var lines []string
	start := p.pos
	if contentIndent < 0 {
		for j := start; j < len(p.lines); j++ {
			if strings.TrimSpace(p.lines[j].raw) == "" {
				continue
			}
			contentIndent = p.lines[j].indent
			break
		}
		if contentIndent <= parentIndent {
			contentIndent = parentIndent + 1
		}
	}
	for p.pos < len(p.lines) {
		raw := p.lines[p.pos].raw
		if strings.TrimSpace(raw) == "" {
			if len(raw) > contentIndent {
				lines = append(lines, raw[contentIndent:])
			} else {
				lines = append(lines, "")
			}
			p.pos++
			continue
		}
		if p.lines[p.pos].indent < contentIndent {
			break
		}
		lines = append(lines, raw[contentIndent:])
		p.pos++
	}
	// trailing blank lines
	trailing := 0
	for len(lines) > 0 && strings.TrimSpace(lines[len(lines)-1]) == "" && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
		trailing++
	}
	// the final "line" of the file after the last newline is not a real line
	if p.pos >= len(p.lines) && trailing > 0 && p.lines[len(p.lines)-1].raw == "" {
		trailing--
	}
	// back up so that blank lines after the scalar are skipped by caller
	var body string
	if literal {
		body = strings.Join(lines, "\n")
	} else {
		body = foldBlock(lines)
	}
	if len(lines) == 0 {
		body = ""
		switch chomp {
		case '+':
			return &ynode{kind: ynScalar, value: strings.Repeat("\n", trailing), quoted: true, line: line}
		default:
			return &ynode{kind: ynScalar, value: "", quoted: true, line: line}
		}
	}
	switch chomp {
	case '-':
	case '+':
		body += "\n" + strings.Repeat("\n", trailing)
	default:
		body += "\n"
	}
	return &ynode{kind: ynScalar, value: body, quoted: true, line: line}
}

func foldBlock(lines []string) string {
	var b strings.Builder
	prevMoreIndented := false
	for i, l := range lines {
		more := strings.HasPrefix(l, " ") || strings.HasPrefix(l, "\t")
		if i > 0 {
			if l == "" {
				b.WriteString("\n")
				continue
			}
			prev := lines[i-1]
			if prev == "" {
				// already wrote newline(s) for empty lines
				if more || prevMoreIndented {
					b.WriteString("\n")
				}
			} else if more || prevMoreIndented {
				b.WriteString("\n")
			} else {
				b.WriteString(" ")
			}
		}
		b.WriteString(l)
		prevMoreIndented = more
	}
	return b.String()
}

// ---- flow parser ----

type flowParser struct {
	s    string
	i    int
	line int
}

func (f *flowParser) skipWS() {
	for f.i < len(f.s) && (f.s[f.i] == ' ' || f.s[f.i] == '\t' || f.s[f.i] == '\n') {
		f.i++
	}
}

func (f *flowParser) parseNode() *ynode {
	f.skipWS()
	if f.i >= len(f.s) {
		yfail(f.line, "did not find expected node content")
	}
	switch f.s[f.i] {
	case '[':
		f.i++
		n := &ynode{kind: ynSeq, line: f.line}
		for {
			f.skipWS()
			if f.i >= len(f.s) {
				yfail(f.line, "did not find expected ',' or ']'")
			}
			if f.s[f.i] == ']' {
				f.i++
				return n
			}
			item := f.parseNode()
			f.skipWS()
			// "a: b" single pair mapping inside sequence
			if f.i < len(f.s) && f.s[f.i] == ':' {
				f.i++
				v := f.parseNode()
				item = &ynode{kind: ynMap, keys: []*ynode{item}, vals: []*ynode{v}, line: f.line}
				f.skipWS()
			}
			n.items = append(n.items, item)
			if f.i >= len(f.s) {
				yfail(f.line, "did not find expected ',' or ']'")
			}
			if f.s[f.i] == ',' {
				f.i++
				continue
			}
			if f.s[f.i] == ']' {
				f.i++
				return n
			}
			yfail(f.line, "did not find expected ',' or ']'")
		}
	case '{':
		f.i++
		n := &ynode{kind: ynMap, line: f.line}
		for {
			f.skipWS()
			if f.i >= len(f.s) {
				yfail(f.line, "did not find expected ',' or '}'")
			}
			if f.s[f.i] == '}' {
				f.i++
				return n
			}
			k := f.parseNode()
			f.skipWS()
			var v *ynode
			if f.i < len(f.s) && f.s[f.i] == ':' {
				f.i++
				f.skipWS()
				if f.i < len(f.s) && (f.s[f.i] == ',' || f.s[f.i] == '}') {
					v = &ynode{kind: ynScalar, isNull: true, line: f.line}
				} else {
					v = f.parseNode()
				}
			} else {
				v = &ynode{kind: ynScalar, isNull: true, line: f.line}
			}
			n.keys = append(n.keys, k)
			n.vals = append(n.vals, v)
			f.skipWS()
			if f.i >= len(f.s) {
				yfail(f.line, "did not find expected ',' or '}'")
			}
			if f.s[f.i] == ',' {
				f.i++
				continue
			}
			if f.s[f.i] == '}' {
				f.i++
				return n
			}
			yfail(f.line, "did not find expected ',' or '}'")
		}
	case '"':
		v, rest := parseDoubleQuoted(f.s[f.i+1:], f.line)
		f.i = len(f.s) - len(rest)
		return &ynode{kind: ynScalar, value: v, quoted: true, line: f.line}
	case '\'':
		v, rest := parseSingleQuoted(f.s[f.i+1:], f.line)
		f.i = len(f.s) - len(rest)
		return &ynode{kind: ynScalar, value: v, quoted: true, line: f.line}
	case ',', ']', '}':
		return &ynode{kind: ynScalar, isNull: true, line: f.line}
	}
	// plain scalar in flow context
	start := f.i
	for f.i < len(f.s) {
		c := f.s[f.i]
		if c == ',' || c == ']' || c == '}' || c == '[' || c == '{' {
			break
		}
		if c == ':' && (f.i+1 >= len(f.s) || f.s[f.i+1] == ' ' || f.s[f.i+1] == ',' || f.s[f.i+1] == ']' || f.s[f.i+1] == '}') {
			break
		}
		if c == '#' && f.i > start && (f.s[f.i-1] == ' ' || f.s[f.i-1] == '\t') {
			break
		}
		f.i++
	}
	v := strings.TrimSpace(f.s[start:f.i])
	v = strings.Join(strings.Fields(v), " ")
	return plainNode(v, f.line)
}
