package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
)

type SubTask struct {
	Summary  string
	Resolved bool
}

type Task struct {
	UUID   string
	Status string
	ID     int

	WritePending bool

	Summary      string
	Notes        string
	Tags         []string
	Project      string
	Priority     string
	DelegatedTo  string
	Subtasks     []SubTask
	Dependencies []string
	Created      time.Time
	Resolved     time.Time
	Due          time.Time

	filtered bool
}

func (t *Task) String() string {
	if t.ID > 0 {
		return fmt.Sprintf("%v: %s", t.ID, t.Summary)
	}
	return t.Summary
}

// ---------- YAML serialisation ----------

func timeYAML(t time.Time) string {
	return t.Format(time.RFC3339Nano)
}

func (t *Task) yamlKVs(withStatus bool) []yKV {
	var kvs []yKV
	if withStatus && t.Status != "" {
		kvs = append(kvs, yKV{"status", ystr(t.Status)})
	}
	subs := make([][]yKV, 0, len(t.Subtasks))
	for _, st := range t.Subtasks {
		subs = append(subs, []yKV{
			{"summary", ystr(st.Summary)},
			{"resolved", yraw(strconv.FormatBool(st.Resolved))},
		})
	}
	kvs = append(kvs,
		yKV{"summary", ystr(t.Summary)},
		yKV{"notes", ystr(t.Notes)},
		yKV{"tags", yseq(t.Tags)},
		yKV{"project", ystr(t.Project)},
		yKV{"priority", ystr(t.Priority)},
		yKV{"delegatedto", ystr(t.DelegatedTo)},
		yKV{"subtasks", ymapseq(subs)},
		yKV{"dependencies", yseq(t.Dependencies)},
		yKV{"created", yraw(timeYAML(t.Created))},
		yKV{"resolved", yraw(timeYAML(t.Resolved))},
		yKV{"due", yraw(timeYAML(t.Due))},
	)
	return kvs
}

func (t *Task) MarshalYAMLFile() []byte {
	return yamlMarshalDoc(t.yamlKVs(false))
}

func (t *Task) MarshalYAMLEdit() []byte {
	return yamlMarshalDoc(t.yamlKVs(true))
}

// ---------- YAML deserialisation (yaml.v2 semantics) ----------

type unmarshalErrors struct {
	errs []string
}

func nodeTagName(n *ynode) string {
	switch n.kind {
	case ynSeq:
		return "!!seq"
	case ynMap:
		return "!!map"
	}
	if n.quoted {
		return "!!str"
	}
	switch resolveTag(n.value) {
	case "int":
		return "!!int"
	case "float":
		return "!!float"
	case "bool":
		return "!!bool"
	case "null":
		return "!!null"
	case "timestamp":
		return "!!timestamp"
	}
	return "!!str"
}

func nodeShortValue(n *ynode) string {
	if n.kind != ynScalar {
		return ""
	}
	v := n.value
	if len(v) > 10 {
		v = v[:7] + "..."
	}
	return " `" + v + "`"
}

func (ue *unmarshalErrors) add(n *ynode, target string) {
	ue.errs = append(ue.errs, fmt.Sprintf("line %d: cannot unmarshal %s%s into %s", n.line, nodeTagName(n), nodeShortValue(n), target))
}

func decodeString(n *ynode, ue *unmarshalErrors) (string, bool) {
	if n.kind != ynScalar {
		ue.add(n, "string")
		return "", false
	}
	if n.isNull && !n.quoted {
		return "", true
	}
	return n.value, true
}

func decodeStringSlice(n *ynode, ue *unmarshalErrors) ([]string, bool) {
	if n.kind == ynScalar {
		if n.isNull && !n.quoted {
			return nil, true
		}
		ue.add(n, "[]string")
		return nil, false
	}
	if n.kind == ynMap {
		ue.add(n, "[]string")
		return nil, false
	}
	out := make([]string, 0, len(n.items))
	for _, it := range n.items {
		s, ok := decodeString(it, ue)
		if ok {
			out = append(out, s)
		} else {
			out = append(out, "")
		}
	}
	return out, true
}

func decodeBool(n *ynode, ue *unmarshalErrors) (bool, bool) {
	if n.kind != ynScalar {
		ue.add(n, "bool")
		return false, false
	}
	if n.isNull && !n.quoted {
		return false, true
	}
	if !n.quoted && resolveTag(n.value) == "bool" {
		switch n.value {
		case "y", "Y", "yes", "Yes", "YES", "true", "True", "TRUE", "on", "On", "ON":
			return true, true
		}
		return false, true
	}
	ue.add(n, "bool")
	return false, false
}

func decodeTime(n *ynode, ue *unmarshalErrors) (time.Time, error, bool) {
	if n.kind != ynScalar {
		ue.add(n, "time.Time")
		return time.Time{}, nil, false
	}
	if n.isNull && !n.quoted {
		return time.Time{}, nil, true
	}
	if !n.quoted {
		if t, ok := yamlParseTimestamp(n.value); ok {
			return t, nil, true
		}
	}
	var t time.Time
	if err := t.UnmarshalText([]byte(n.value)); err != nil {
		return time.Time{}, err, false
	}
	return t, nil, true
}

