func (t *Task) MatchesFilter(q Query) bool {
	if len(q.IDs) > 0 {
		found := false
		for _, id := range q.IDs {
			if id == t.ID {
				found = true
				break
			}
		}
		if !found {
			return false
		}
		if q.Text != "" && !t.matchesText(q.Text) {
			return false
		}
		return true
	}

	for _, tag := range q.Tags {
		if !t.HasTag(tag) {
			return false
		}
	}
	for _, tag := range q.AntiTags {
		if t.HasTag(tag) {
			return false
		}
	}
	if q.Project != "" && t.Project != q.Project {
		return false
	}
	for _, p := range q.AntiProjects {
		if t.Project == p {
			return false
		}
	}
	if !q.Due.IsZero() {
		if t.Due.IsZero() {
			return false
		}
		due := startOfDay(t.Due)
		qd := startOfDay(q.Due)
		switch q.DateFilter {
		case "before":
			if due.After(qd) {
				return false
			}
		case "after":
			if due.Before(qd) {
				return false
			}
		default: // "", "on", "in"
			if !due.Equal(qd) {
				return false
			}
		}
	}
	if q.Priority != "" && t.Priority != q.Priority {
		return false
	}
	if q.Text != "" && !t.matchesText(q.Text) {
		return false
	}
	return true
}

func (t *Task) matchesText(text string) bool {
	lt := strings.ToLower(text)
	return strings.Contains(strings.ToLower(t.Summary+" "+t.Notes), lt)
}

func appendNote(notes, text string) string {
	if notes == "" {
		return text
	}
	return notes + "\n" + text
}
