package main

import (
	"encoding/gob"
	"fmt"
	"log"
	"os"
	"path"
	"sort"
	"time"
)

type IdsMap map[string]int

type TaskSet struct {
	tasks        []*Task
	tasksByID    map[int]*Task
	tasksByUUID  map[string]*Task
	usedIDs      map[int]bool
	idsMap       IdsMap
	repoPath     string
	idsFilePath  string
}

func loadIDs(idsFilePath string) IdsMap {
	ids := IdsMap{}
	f, err := os.Open(idsFilePath)
	if err != nil {
		return ids
	}
	defer f.Close()
	dec := gob.NewDecoder(f)
	if err := dec.Decode(&ids); err != nil {
		return IdsMap{}
	}
	return ids
}

func saveIDs(idsFilePath string, ids IdsMap) {
	os.MkdirAll(path.Dir(idsFilePath), 0755)
	f, err := os.Create(idsFilePath)
	if err != nil {
		exitFail(err.Error())
	}
	defer f.Close()
	enc := gob.NewEncoder(f)
	if err := enc.Encode(ids); err != nil {
		exitFail(err.Error())
	}
}

func LoadTaskSet(repoPath, idsFilePath string, includeResolved bool) *TaskSet {
	ts := &TaskSet{
		tasksByID:   map[int]*Task{},
		tasksByUUID: map[string]*Task{},
		usedIDs:     map[int]bool{},
		repoPath:    repoPath,
		idsFilePath: idsFilePath,
	}
	ts.idsMap = loadIDs(idsFilePath)

	for _, status := range ALL_STATUSES {
		if status == STATUS_RESOLVED && !includeResolved {
			continue
		}
		dir := path.Join(repoPath, status)
		entries, err := os.ReadDir(dir)
		if err != nil {
			continue
		}
		for _, entry := range entries {
			name := entry.Name()
			if len(name) > 0 && name[0] == '.' {
				continue
			}
			t, err := loadTaskFile(dir, name, status)
			if err != nil {
				log.Printf("error loading task: %s\n", err)
				continue
			}
			ts.addTask(t)
		}
	}
	return ts
}

func loadTaskFile(dir, name, status string) (*Task, error) {
	if len(name) != 40 {
		return nil, fmt.Errorf("filename does not encode UUID %s (wrong length)", name)
	}
	uuid := name[:36]
	if !isValidUUID4String(uuid) {
		return nil, fmt.Errorf("filename does not encode UUID %s", name)
	}
	data, err := os.ReadFile(path.Join(dir, name))
	if err != nil {
		return nil, fmt.Errorf("failed to read %s", name)
	}
	t := &Task{UUID: uuid, Status: status}
	if err := UnmarshalYAMLInto(data, t, false); err != nil {
		return nil, fmt.Errorf("failed to unmarshal %s", name)
	}
	t.UUID = uuid
	t.Status = status
	if t.Priority == "" {
		t.Priority = PRIORITY_NORMAL
	}
	if err := t.Validate(); err != nil {
		return nil, err
	}
	return t, nil
}

func (ts *TaskSet) nextFreeID() int {
	for id := 1; ; id++ {
		if !ts.usedIDs[id] {
			return id
		}
	}
}

// addTask adds a task loaded from disk or newly created, assigning an ID
func (ts *TaskSet) addTask(t *Task) *Task {
	t.normalise()
	if t.Created.IsZero() {
		t.Created = time.Now()
	}
	if t.Priority == "" {
		t.Priority = PRIORITY_NORMAL
	}
	if t.Status != STATUS_RESOLVED {
		if id, ok := ts.idsMap[t.UUID]; ok && id > 0 && !ts.usedIDs[id] {
			t.ID = id
		} else {
			t.ID = ts.nextFreeID()
		}
		ts.usedIDs[t.ID] = true
		ts.tasksByID[t.ID] = t
	} else {
		t.ID = 0
	}
	ts.tasks = append(ts.tasks, t)
	ts.tasksByUUID[t.UUID] = t
	return t
}

// LoadNewTask adds a newly created task to the set
func (ts *TaskSet) LoadNewTask(t *Task) *Task {
	if t.UUID == "" {
		t.UUID = newUUID4()
	}
	t.WritePending = true
	return ts.addTask(t)
}

func (ts *TaskSet) GetByID(id int) (*Task, error) {
	if t, ok := ts.tasksByID[id]; ok {
		return t, nil
	}
	return nil, fmt.Errorf("no open task with ID %v exists", id)
}

func (ts *TaskSet) MustGetByID(id int) *Task {
	t, err := ts.GetByID(id)
	if err != nil {
		exitFail(err.Error())
	}
	return t
}

// UpdateTask replaces a task with a modified copy, checking status transitions
func (ts *TaskSet) UpdateTask(t *Task, newStatus string) error {
	old := ts.tasksByUUID[t.UUID]
	if old == nil {
		return fmt.Errorf("task not found")
	}
	if newStatus != old.Status {
		if !isValidStateTransition(old.Status, newStatus) {
			return fmt.Errorf("invalid state transition: %s -> %s", old.Status, newStatus)
		}
	}
	t.Status = newStatus
	if newStatus == STATUS_RESOLVED && t.Resolved.IsZero() {
		t.Resolved = time.Now()
	}
	t.normalise()
	t.WritePending = true
	return nil
}

func (ts *TaskSet) AllTasks() []*Task {
	return ts.tasks
}

func (ts *TaskSet) Tasks() []*Task {
	var out []*Task
	for _, t := range ts.tasks {
		if !t.filtered {
			out = append(out, t)
		}
	}
	return out
}

func (ts *TaskSet) Filter(q Query) {
	for _, t := range ts.tasks {
		if !t.MatchesFilter(q) {
			t.filtered = true
		}
	}
}

func (ts *TaskSet) FilterByStatus(statuses ...string) {
	for _, t := range ts.tasks {
		if !strSliceContains(statuses, t.Status) {
			t.filtered = true
		}
	}
}

func (ts *TaskSet) FilterOrganised() {
	for _, t := range ts.tasks {
		if len(t.Tags) > 0 || t.Project != "" {
			t.filtered = true
		}
	}
}

func (ts *TaskSet) UnHide() {
	for _, t := range ts.tasks {
		t.filtered = false
	}
}

func (ts *TaskSet) SortByPriority() {
	sort.SliceStable(ts.tasks, func(i, j int) bool {
		a, b := ts.tasks[i], ts.tasks[j]
		if a.Priority == b.Priority {
			return a.Created.Before(b.Created)
		}
		return a.Priority < b.Priority
	})
}

func (ts *TaskSet) SortByResolved() {
	sort.SliceStable(ts.tasks, func(i, j int) bool {
		return ts.tasks[i].Resolved.Before(ts.tasks[j].Resolved)
	})
}

func (ts *TaskSet) savePendingChanges() {
	for _, t := range ts.tasks {
		if t.WritePending {
			ts.saveTaskToDisk(t)
			t.WritePending = false
		}
	}
	ids := IdsMap{}
	for _, t := range ts.tasks {
		if t.ID > 0 && t.Status != STATUS_RESOLVED {
			ids[t.UUID] = t.ID
		}
	}
	saveIDs(ts.idsFilePath, ids)
}

func (ts *TaskSet) saveTaskToDisk(t *Task) {
	for _, st := range ALL_STATUSES {
		os.MkdirAll(path.Join(ts.repoPath, st), 0700)
	}
	filename := t.UUID + ".yml"
	filepath := path.Join(ts.repoPath, t.Status, filename)
	data := t.MarshalYAMLFile()
	if err := os.WriteFile(filepath, data, 0600); err != nil {
		exitFail(err.Error())
	}
	// remove from other status dirs
	for _, st := range ALL_STATUSES {
		if st == t.Status {
			continue
		}
		p := path.Join(ts.repoPath, st, filename)
		if _, err := os.Stat(p); err == nil {
			os.Remove(p)
		}
	}
}

func (ts *TaskSet) deleteTaskFromDisk(t *Task) {
	filename := t.UUID + ".yml"
	p := path.Join(ts.repoPath, t.Status, filename)
	if err := os.Remove(p); err != nil {
		exitFail(err.Error())
	}
}

// GetTags returns the set of tags in the (filtered) task set
func (ts *TaskSet) GetTags() map[string]bool {
	tags := map[string]bool{}
	for _, t := range ts.Tasks() {
		for _, tag := range t.Tags {
			tags[tag] = true
		}
	}
	return tags
}

func sortedKeys(m map[string]bool) []string {
	var out []string
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

type Project struct {
	Name          string    `json:"name"`
	TaskCount     int       `json:"taskCount"`
	ResolvedCount int       `json:"resolvedCount"`
	Active        bool      `json:"active"`
	Created       time.Time `json:"created"`
	Resolved      time.Time `json:"resolved"`
	Priority      string    `json:"priority"`
}

func (ts *TaskSet) GetProjects() []*Project {
	projects := map[string]*Project{}
	for _, t := range ts.AllTasks() {
		name := t.Project
		if name == "" {
			continue
		}
		p, ok := projects[name]
		if !ok {
			p = &Project{Name: name, Priority: PRIORITY_LOW}
			projects[name] = p
		}
		p.TaskCount++
		if p.Created.IsZero() || t.Created.Before(p.Created) {
			p.Created = t.Created
		}
		if t.Resolved.After(p.Resolved) {
			p.Resolved = t.Resolved
		}
		if t.Status == STATUS_RESOLVED {
			p.ResolvedCount++
		} else {
			if t.Priority < p.Priority {
				p.Priority = t.Priority
			}
		}
		if t.Status == STATUS_ACTIVE {
			p.Active = true
		}
	}
	var names []string
	for n := range projects {
		names = append(names, n)
	}
	sort.Strings(names)
	var out []*Project
	for _, n := range names {
		out = append(out, projects[n])
	}
	return out
}
