func (ts *TaskSet) UpdateTask(t *Task, newStatus string) error {
	old := ts.tasksByUUID[t.UUID]
	if old == nil {
		return fmt.Errorf("task not found")
	}
	if newStatus != old.Status {
		if !isValidStateTransition(old.Status, newStatus) {
			return fmt.Errorf("invalid state transition: %s -> %s", old.Status, newStatus)
		}
	}
	t.Status = newStatus
	if newStatus == STATUS_RESOLVED && t.Resolved.IsZero() {
		t.Resolved = time.Now()
	}
	t.normalise()
	t.WritePending = true
	return nil
}

func (ts *TaskSet) AllTasks() []*Task {
	return ts.tasks
}

func (ts *TaskSet) Tasks() []*Task {
	var out []*Task
	for _, t := range ts.tasks {
		if !t.filtered {
			out = append(out, t)
		}
	}
	return out
}

func (ts *TaskSet) Filter(q Query) {
	for _, t := range ts.tasks {
		if !t.MatchesFilter(q) {
			t.filtered = true
		}
	}
}

func (ts *TaskSet) FilterByStatus(statuses ...string) {
	for _, t := range ts.tasks {
		if !strSliceContains(statuses, t.Status) {
			t.filtered = true
		}
	}
}

func (ts *TaskSet) FilterOrganised() {
	for _, t := range ts.tasks {
		if len(t.Tags) > 0 || t.Project != "" {
			t.filtered = true
		}
	}
}

func (ts *TaskSet) UnHide() {
	for _, t := range ts.tasks {
		t.filtered = false
	}
}

func (ts *TaskSet) SortByPriority() {
	sort.SliceStable(ts.tasks, func(i, j int) bool {
		a, b := ts.tasks[i], ts.tasks[j]
		if a.Priority == b.Priority {
			return a.Created.Before(b.Created)
		}
		return a.Priority < b.Priority
	})
}

func (ts *TaskSet) SortByResolved() {
	sort.SliceStable(ts.tasks, func(i, j int) bool {
		return ts.tasks[i].Resolved.Before(ts.tasks[j].Resolved)
	})
}

func (ts *TaskSet) savePendingChanges() {
	for _, t := range ts.tasks {
		if t.WritePending {
			ts.saveTaskToDisk(t)
			t.WritePending = false
		}
	}
	ids := IdsMap{}
	for _, t := range ts.tasks {
		if t.ID > 0 && t.Status != STATUS_RESOLVED {
			ids[t.UUID] = t.ID
		}
	}
	saveIDs(ts.idsFilePath, ids)
}

func (ts *TaskSet) saveTaskToDisk(t *Task) {
	for _, st := range ALL_STATUSES {
		os.MkdirAll(path.Join(ts.repoPath, st), 0700)
	}
	filename := t.UUID + ".yml"
	filepath := path.Join(ts.repoPath, t.Status, filename)
	data := t.MarshalYAMLFile()
	if err := os.WriteFile(filepath, data, 0600); err != nil {
		exitFail(err.Error())
	}
	// remove from other status dirs
	for _, st := range ALL_STATUSES {
		if st == t.Status {
			continue
		}
		p := path.Join(ts.repoPath, st, filename)
		if _, err := os.Stat(p); err == nil {
			os.Remove(p)
		}
	}
}

func (ts *TaskSet) deleteTaskFromDisk(t *Task) {
	filename := t.UUID + ".yml"
	p := path.Join(ts.repoPath, t.Status, filename)
	if err := os.Remove(p); err != nil {
		exitFail(err.Error())
	}
}

// GetTags returns the set of tags in the (filtered) task set
func (ts *TaskSet) GetTags() map[string]bool {
	tags := map[string]bool{}
	for _, t := range ts.Tasks() {
		for _, tag := range t.Tags {
			tags[tag] = true
		}
	}
	return tags
}

func sortedKeys(m map[string]bool) []string {
	var out []string
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

type Project struct {
	Name          string    `json:"name"`
	TaskCount     int       `json:"taskCount"`
	ResolvedCount int       `json:"resolvedCount"`
	Active        bool      `json:"active"`
	Created       time.Time `json:"created"`
	Resolved      time.Time `json:"resolved"`
	Priority      string    `json:"priority"`
}

func (ts *TaskSet) GetProjects() []*Project {
	projects := map[string]*Project{}
	for _, t := range ts.AllTasks() {
		name := t.Project
		if name == "" {
			continue
		}
		p, ok := projects[name]
		if !ok {
			p = &Project{Name: name, Priority: PRIORITY_LOW}
			projects[name] = p
		}
		p.TaskCount++
		if p.Created.IsZero() || t.Created.Before(p.Created) {
			p.Created = t.Created
		}
		if t.Resolved.After(p.Resolved) {
			p.Resolved = t.Resolved
		}
		if t.Status == STATUS_RESOLVED {
			p.ResolvedCount++
		} else {
			if t.Priority < p.Priority {
				p.Priority = t.Priority
			}
		}
		if t.Status == STATUS_ACTIVE {
			p.Active = true
		}
	}
	var names []string
	for n := range projects {
		names = append(names, n)
	}
	sort.Strings(names)
	var out []*Project
	for _, n := range names {
		out = append(out, projects[n])
	}
	return out
}
