func inRanges(r rune, table []runeRange) bool {
	lo, hi := 0, len(table)-1
	for lo <= hi {
		m := (lo + hi) / 2
		if r < table[m].lo {
			hi = m - 1
		} else if r > table[m].hi {
			lo = m + 1
		} else {
			return true
		}
	}
	return false
}

func isZeroWidthFormat(r rune) bool {
	switch {
	case r >= 0x200B && r <= 0x200F:
		return true
	case r >= 0x2028 && r <= 0x202E:
		return true
	case r >= 0x2060 && r <= 0x2063:
		return true
	case r == 0xFEFF:
		return true
	}
	return false
}

// RuneWidth approximates go-runewidth's RuneWidth with EastAsianWidth=false
func RuneWidth(r rune) int {
	switch {
	case r < 0 || r > 0x10FFFF:
		return 0
	case r < 0x20:
		return 0
	case (r >= 0x7F && r <= 0x9F) || r == 0xAD:
		return 0
	case r < 0x300:
		return 1
	case isZeroWidthFormat(r):
		return 0
	case unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r):
		return 0
	case inRanges(r, doubleWidthTable):
		return 2
	}
	return 1
}

func isGraphemeExtend(r rune) bool {
	if r == 0x200D || (r >= 0xFE00 && r <= 0xFE0F) || (r >= 0x1F3FB && r <= 0x1F3FF) || (r >= 0xE0020 && r <= 0xE007F) {
		return true
	}
	return unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) || unicode.Is(unicode.Mc, r)
}

type grapheme struct {
	start, end int // byte offsets
	width      int
}

func graphemes(s string) []grapheme {
	var out []grapheme
	var cur *grapheme
	prevZWJ := false
	riCount := 0
	for i, r := range s {
		size := len(string(r))
		join := false
		if cur != nil {
			if isGraphemeExtend(r) {
				join = true
			} else if prevZWJ && RuneWidth(r) > 0 && r >= 0x2000 {
				join = true
			} else if r >= 0x1F1E6 && r <= 0x1F1FF && riCount%2 == 1 {
				join = true
			}
		}
		if r == '\r' || r == '\n' || r < 0x20 {
			join = false
		}
		if join {
			cur.end = i + size
			if cur.width == 0 {
				cur.width = RuneWidth(r)
			}
		} else {
			out = append(out, grapheme{start: i, end: i + size, width: RuneWidth(r)})
			cur = &out[len(out)-1]
		}
		prevZWJ = r == 0x200D
		if r >= 0x1F1E6 && r <= 0x1F1FF {
			riCount++
		} else {
			riCount = 0
		}
		if cur != nil && cur != &out[len(out)-1] {
			cur = &out[len(out)-1]
		}
	}
	return out
}

func StringWidth(s string) int {
	w := 0
	for _, g := range graphemes(s) {
		w += g.width
	}
	return w
}

func Truncate(s string, w int) string {
	if StringWidth(s) <= w {
		return s
	}
	width := 0
	pos := len(s)
	for _, g := range graphemes(s) {
		if width+g.width > w {
			pos = g.start
			break
		}
		width += g.width
	}
	return s[:pos]
}
