func (t *Task) Style() RowStyle {
	now := time.Now()
	style := RowStyle{}
	overdue := !t.Due.IsZero() && t.Due.Before(now)

	if t.Priority == PRIORITY_CRITICAL {
		style.Fg = FG_PRIORITY_CRITICAL
	} else if overdue {
		style.Fg = FG_PRIORITY_HIGH
	} else if t.Priority == PRIORITY_HIGH {
		style.Fg = FG_PRIORITY_HIGH
	} else if t.Priority == PRIORITY_LOW {
		style.Fg = FG_PRIORITY_LOW
	}

	if t.Status == STATUS_ACTIVE {
		switch style.Fg {
		case FG_PRIORITY_CRITICAL:
			style.Fg = FG_ACTIVE_CRITICAL
		case FG_PRIORITY_HIGH:
			style.Fg = FG_ACTIVE_HIGH
		case FG_PRIORITY_LOW:
			style.Fg = FG_ACTIVE_LOW
		default:
			style.Fg = FG_ACTIVE
		}
		style.Bg = BG_ACTIVE
	} else if t.Status == STATUS_PAUSED {
		style.Bg = BG_PAUSED
	}
	return style
}

func (t *Task) ParseDueDateToStr() string {
	if t.Due.IsZero() {
		return ""
	}
	now := time.Now()
	today := startOfDay(now)
	due := t.Due
	dueDay := time.Date(due.Year(), due.Month(), due.Day(), 0, 0, 0, 0, today.Location())
	days := int(dueDay.Sub(today).Hours() / 24)
	if dueDay.Before(today) && dueDay.Sub(today)%(24*time.Hour) != 0 {
		days--
	}
	switch {
	case days == 0:
		return "today"
	case days == 1:
		return "tomorrow"
	case days == -1:
		return "yesterday"
	case days > 1 && days < 7:
		return due.Format("Mon _2")
	case due.Year() == now.Year():
		return due.Format("_2 Jan")
	}
	return due.Format("_2 Jan 2006")
}

func taskTags(t *Task) string {
	return strings.Join(t.Tags, " ")
}

