func displayTasksTable(tasks []*Task, truncate bool) {
	w, h := termSize()
	total := len(tasks)
	maxTasks := h - TERMINAL_HEIGHT_MARGIN
	if maxTasks < MIN_TASKS_SHOWN {
		maxTasks = MIN_TASKS_SHOWN
	}
