cat > git.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
)

func gitCmd(repoPath string, args ...string) *exec.Cmd {
	cmd := exec.Command("git", append([]string{"-C", repoPath}, args...)...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd
}

func runGitCmd(repoPath string, args ...string) error {
	return gitCmd(repoPath, args...).Run()
}

func mustRunGitCmd(repoPath string, args ...string) {
	if err := runGitCmd(repoPath, args...); err != nil {
		exitFail("Failed to run git cmd.")
	}
}

func gitCommit(repoPath string, format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	fmt.Fprintf(stdout, "\n%s\n", msg)
	fmt.Fprintf(stdout, "\033[38;5;245m")

	if err := runGitCmd(repoPath, "add", "."); err != nil {
		exitFailf("error: failed to add files: %v", err)
	}

	cmd := exec.Command("git", "-C", repoPath, "status", "--porcelain")
	out, err := cmd.Output()
	if err == nil && len(strings.TrimSpace(string(out))) == 0 {
		fmt.Fprintf(stdout, "No changes detected\n")
		fmt.Fprintf(stdout, "\033[0m")
		return
	}

	if err := runGitCmd(repoPath, "commit", "--no-gpg-sign", "-m", msg); err != nil {
		exitFailf("error: failed to commit changes: %v", err)
	}
	fmt.Fprintf(stdout, "\033[0m")
}

func ensureRepoExists(repoPath string) {
	gitDir := repoPath + "/.git"
	if _, err := os.Stat(gitDir); os.IsNotExist(err) {
		if err := os.MkdirAll(repoPath, 0700); err != nil {
			exitFail(err.Error())
		}
		mustRunGitCmd(repoPath, "init")
		fmt.Fprintf(stdout, "\nAdd a remote repository with:\n\n\tdstask git remote add origin <repo>\n\n")
	}
}
