package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strconv"
	"time"
)

func printContextDescription(ctx Query) {
	envVarNotification := ""
	if os.Getenv("DSTASK_CONTEXT") != "" {
		envVarNotification = " (set by DSTASK_CONTEXT)"
	}
	if s := ctx.String(); s != "" {
		fmt.Fprintf(stdout, "\033[33mActive context%s: %s\033[0m\n", envVarNotification, s)
	}
}

func mustMerge(q, ctx Query) Query {
	out, err := q.Merge(ctx)
	if err != nil {
		exitFail(err.Error())
	}
	return out
}

// displayByNext renders the filtered task set as a table/single task, or JSON
func (ts *TaskSet) displayByNext(ctx Query, truncate bool, criticalWarning bool) error {
	if stdoutIsTTY() {
		printContextDescription(ctx)
		if len(ts.AllTasks()) == 0 {
			fmt.Fprintf(stdout, "No tasks found. Run `dstask help` for instructions.\n")
			return nil
		}
		tasks := ts.Tasks()
		if len(tasks) == 0 {
			return errors.New("No matching tasks in given context or filter.")
		}
		if len(tasks) == 1 {
			displaySingleTask(tasks[0])
		} else {
			displayTasksTable(tasks, truncate)
		}
		if criticalWarning {
			ts.displayCriticalTaskWarning(tasks)
		}
		return nil
	}
	return renderTasksJSON(ts.Tasks())
}

func commandShowList(conf Config, ctx, query Query, statuses []string, truncate bool) error {
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	if len(query.IDs) > 0 {
		if query.HasOperators() {
			return errors.New("operators not valid when addressing task by ID")
		}
	} else {
		query = mustMerge(query, ctx)
	}
	ts.Filter(query)
	ts.FilterByStatus(statuses...)
	ts.SortByPriority()
	return ts.displayByNext(ctx, truncate, true)
}

func CommandNext(conf Config, ctx, query Query) error {
	return commandShowList(conf, ctx, query, OPEN_STATUSES, true)
}

func CommandShowOpen(conf Config, ctx, query Query) error {
	return commandShowList(conf, ctx, query, OPEN_STATUSES, false)
}

func CommandShowActive(conf Config, ctx, query Query) error {
	return commandShowList(conf, ctx, query, []string{STATUS_ACTIVE}, true)
}

func CommandShowPaused(conf Config, ctx, query Query) error {
	return commandShowList(conf, ctx, query, []string{STATUS_PAUSED}, true)
}

func CommandShowTemplates(conf Config, ctx, query Query) error {
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	if len(query.IDs) > 0 {
		if query.HasOperators() {
			return errors.New("operators not valid when addressing task by ID")
		}
	} else {
		query = mustMerge(query, ctx)
	}
	ts.Filter(query)
	ts.FilterByStatus(STATUS_TEMPLATE)
	ts.SortByPriority()
	return ts.displayByNext(ctx, true, false)
}

func CommandShowUnorganised(conf Config, ctx, query Query) error {
	if len(query.IDs) > 0 || query.HasOperators() {
		return errors.New("query/context not used for show-unorganised")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	ts.FilterOrganised()
	ts.FilterByStatus(OPEN_STATUSES...)
	ts.SortByPriority()
	return ts.displayByNext(ctx, true, true)
}

func CommandShowResolved(conf Config, ctx, query Query) error {
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, true)
	if len(query.IDs) > 0 {
		if query.HasOperators() {
			return errors.New("operators not valid when addressing task by ID")
		}
	} else {
		query = mustMerge(query, ctx)
	}
	ts.Filter(query)
	ts.FilterByStatus(STATUS_RESOLVED)
	ts.SortByResolved()
	tasks := ts.Tasks()
	if len(tasks) > MAX_RESOLVED_SHOWN {
		tasks = tasks[len(tasks)-MAX_RESOLVED_SHOWN:]
	}
	if isTerminal(os.Stdout.Fd()) {
		displayResolved(tasks)
		return nil
	}
	return renderTasksJSON(tasks)
}

func CommandShowProjects(conf Config, ctx, query Query) error {
	if len(query.IDs) > 0 || query.HasOperators() {
		return errors.New("query/context not supported for show-projects")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, true)
	if stdoutIsTTY() {
		ts.displayProjects()
		return nil
	}
	projects := ts.GetProjects()
	if projects == nil {
		projects = []*Project{}
	}
	data, err := json.MarshalIndent(projects, "", "  ")
	if err != nil {
		return err
	}
	stdout.Write(data)
	return nil
}

func CommandShowTags(conf Config, ctx, query Query) error {
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	if len(query.IDs) == 0 {
		query = mustMerge(query, ctx)
	}
	ts.Filter(query)
	ts.FilterByStatus(OPEN_STATUSES...)
	for _, tag := range sortedKeys(ts.GetTags()) {
		fmt.Fprintf(stdout, "%s\n", tag)
	}
	return nil
}

func CommandAdd(conf Config, ctx, query Query) error {
	if query.DateFilter != "" {
		return errors.New("cannot use date filter with add command")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)

	if query.Template > 0 {
		tt := ts.MustGetByID(query.Template)
		query = mustMerge(query, ctx)
		task := &Task{
			Status:   STATUS_PENDING,
			Summary:  tt.Summary,
			Tags:     append([]string{}, tt.Tags...),
			Project:  tt.Project,
			Priority: tt.Priority,
			Notes:    tt.Notes,
			Due:      tt.Due,
		}
		if query.Text != "" {
			task.Summary = query.Text
		}
		task.Notes = appendNote(task.Notes, query.Note)
		task.Modify(query)
		task = ts.LoadNewTask(task)
		ts.savePendingChanges()
		gitCommit(conf.Repo, "Added %s", task)
		if tt.Status != STATUS_TEMPLATE {
			fmt.Fprintf(stdout, "\nYou've copied an open task!\n")
			fmt.Fprintf(stdout, "To learn more about creating templates enter 'dstask help template'\n\n")
		}
		return nil
	}

	if query.Text == "" {
		return errors.New("task description or template required")
	}

	printContextDescription(ctx)
	query = mustMerge(query, ctx)
	task := &Task{
		Status:   STATUS_PENDING,
		Summary:  query.Text,
		Tags:     query.Tags,
		Project:  query.Project,
		Priority: query.Priority,
		Notes:    query.Note,
		Due:      query.Due,
	}
	task = ts.LoadNewTask(task)
	ts.savePendingChanges()
	gitCommit(conf.Repo, "Added %s", task)
	return nil
}

func CommandLog(conf Config, ctx, query Query) error {
	if query.Text == "" {
		return errors.New("task description required")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	printContextDescription(ctx)
	query = mustMerge(query, ctx)
	task := &Task{
		Status:   STATUS_RESOLVED,
		Summary:  query.Text,
		Tags:     query.Tags,
		Project:  query.Project,
		Priority: query.Priority,
		Notes:    query.Note,
		Due:      query.Due,
		Resolved: time.Now(),
	}
	task = ts.LoadNewTask(task)
	ts.savePendingChanges()
	gitCommit(conf.Repo, "Logged %s", task)
	return nil
}

func CommandTemplate(conf Config, ctx, query Query) error {
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	if len(query.IDs) > 0 {
		for _, id := range query.IDs {
			task := ts.MustGetByID(id)
			if err := ts.UpdateTask(task, STATUS_TEMPLATE); err != nil {
				return err
			}
			ts.savePendingChanges()
			gitCommit(conf.Repo, "Changed %s to Template", task)
		}
		return nil
	}
	if query.Text != "" {
		query = mustMerge(query, ctx)
		task := &Task{
			Status:   STATUS_TEMPLATE,
			Summary:  query.Text,
			Tags:     query.Tags,
			Project:  query.Project,
			Priority: query.Priority,
			Notes:    query.Note,
			Due:      query.Due,
		}
		task = ts.LoadNewTask(task)
		ts.savePendingChanges()
		gitCommit(conf.Repo, "Created Template %s", task)
	}
	return nil
}

func CommandStart(conf Config, ctx, query Query) error {
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	if len(query.IDs) > 0 {
		for _, id := range query.IDs {
			task := ts.MustGetByID(id)
			if err := ts.UpdateTask(task, STATUS_ACTIVE); err != nil {
				return err
			}
			if query.Text != "" {
				task.Notes += "\n" + query.Text
			}
			ts.savePendingChanges()
			gitCommit(conf.Repo, "Started %s", task)
			if task.Notes != "" {
				printNotes(task)
			}
		}
		return nil
	}
	if query.Text != "" {
		query = mustMerge(query, ctx)
		task := &Task{
			Status:   STATUS_ACTIVE,
			Summary:  query.Text,
			Tags:     query.Tags,
			Project:  query.Project,
			Priority: query.Priority,
			Notes:    query.Note,
			Due:      query.Due,
		}
		task = ts.LoadNewTask(task)
		ts.savePendingChanges()
		gitCommit(conf.Repo, "Added and started %s", task)
		return nil
	}
	return errors.New("nothing to do -- specify an ID or describe a task")
}

func CommandStop(conf Config, ctx, query Query) error {
	if len(query.IDs) == 0 {
		return errors.New("no ID(s) specified")
	}
	if query.HasOperators() {
		return errors.New("operators not valid in this context")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
		if err := ts.UpdateTask(task, STATUS_PAUSED); err != nil {
			return err
		}
		if query.Text != "" {
			task.Notes += "\n" + query.Text
		}
		ts.savePendingChanges()
		gitCommit(conf.Repo, "Stopped %s", task)
	}
	return nil
}

func CommandDone(conf Config, ctx, query Query) error {
	if len(query.IDs) == 0 {
		return errors.New("no ID(s) specified")
	}
	if query.HasOperators() {
		return errors.New("operators not valid in this context")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
		if err := ts.UpdateTask(task, STATUS_RESOLVED); err != nil {
			return err
		}
		if query.Text != "" {
			task.Notes += "\n" + query.Text
		}
		ts.savePendingChanges()
		gitCommit(conf.Repo, "Resolved %s", task)
	}
	return nil
}

func CommandRemove(conf Config, ctx, query Query) error {
	if len(query.IDs) == 0 {
		return errors.New("no ID(s) specified")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
		fmt.Fprintf(stdout, "%s\n", task)
		ts.deleteTaskFromDisk(task)
		ts.removeTask(task)
		ts.savePendingChanges()
		gitCommit(conf.Repo, "Removed: %s", task)
	}
	return nil
}

func (ts *TaskSet) removeTask(t *Task) {
	var out []*Task
	for _, x := range ts.tasks {
		if x != t {
			out = append(out, x)
		}
	}
	ts.tasks = out
	delete(ts.tasksByUUID, t.UUID)
	if t.ID > 0 {
		delete(ts.tasksByID, t.ID)
		delete(ts.usedIDs, t.ID)
	}
}

func CommandModify(conf Config, ctx, query Query) error {
	if !query.HasOperators() {
		return errors.New("no operations specified")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	if len(query.IDs) == 0 {
		ts.Filter(ctx)
		ts.FilterByStatus(OPEN_STATUSES...)
		tasks := ts.Tasks()
		if stdoutIsTTY() {
			confirmOrAbort("no IDs specified. Apply to all %d tasks in current ctx?", len(tasks))
		}
		for _, task := range tasks {
			task.Modify(query)
			task.normalise()
			task.WritePending = true
			ts.savePendingChanges()
			gitCommit(conf.Repo, "Modified %s", task)
		}
		return nil
	}
	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
		task.Modify(query)
		task.normalise()
		task.WritePending = true
		ts.savePendingChanges()
		gitCommit(conf.Repo, "Modified %s", task)
	}
	return nil
}

func CommandEdit(conf Config, ctx, query Query) error {
	if len(query.IDs) == 0 {
		return errors.New("no ID(s) specified")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
		data := task.MarshalYAMLEdit()
		var edited Task
		for {
			out := editBytes(data, makeTempFilename(task.ID, task.Summary, "yml"))
			edited = *task
			err := UnmarshalYAMLInto(out, &edited, true)
			if err == nil {
				break
			}
			fmt.Fprintf(stderr, "Failed to unmarshal %s\n", err)
			confirmOrAbort("Try again?")
		}
		edited.UUID = task.UUID
		edited.ID = task.ID
		newStatus := edited.Status
		if err := edited.Validate(); err != nil {
			return fmt.Errorf("%s, task %s", err, task.UUID)
		}
		edited.Status = task.Status
		*task = edited
		if err := ts.UpdateTask(task, newStatus); err != nil {
			return err
		}
		ts.savePendingChanges()
		gitCommit(conf.Repo, "Edited %s", task)
	}
	return nil
}

func CommandNote(conf Config, ctx, query Query) error {
	if len(query.IDs) == 0 {
		return errors.New("no ID(s) specified")
	}
	if query.HasOperators() {
		return errors.New("operators not valid in this context")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
		if !stdoutIsTTY() {
			fmt.Fprint(stdout, task.Notes)
			continue
		}
		if query.Text == "" {
			out := editBytes([]byte(task.Notes), makeTempFilename(task.ID, task.Summary, "md"))
			task.Notes = string(out)
		} else {
			task.Notes = appendNote(task.Notes, query.Text)
		}
		task.WritePending = true
		ts.savePendingChanges()
		gitCommit(conf.Repo, "Edit note %s", task)
	}
	return nil
}

func CommandOpen(conf Config, ctx, query Query) error {
	if len(query.IDs) == 0 {
		return errors.New("no ID(s) specified")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
		urls := findURLs(task.Summary + " " + task.Notes)
		if len(urls) == 0 {
			return fmt.Errorf("no URLs found in task %v", task.ID)
		}
		for _, url := range urls {
			if err := openBrowser(url); err != nil {
				return errors.New("Failed to open browser")
			}
		}
	}
	return nil
}

func openBrowser(url string) error {
	cmd := exec.Command("xdg-open", url)
	return cmd.Run()
}

func CommandContext(conf Config, state State, ctx, query Query, args []string) error {
	if len(args) < 3 {
		fmt.Fprintf(stdout, "%s\n", ctx)
		return nil
	}
	if conf.CtxFromEnvVar != "" {
		return errors.New("setting context not allowed while DSTASK_CONTEXT is set")
	}
	if args[2] == "none" {
		state.Context = Query{}
		state.Save(conf.StateFile)
		return nil
	}
	if len(query.IDs) > 0 {
		return errors.New("context cannot contain IDs")
	}
	if query.Text != "" {
		return errors.New("context cannot contain text")
	}
	state.Context = query
	state.Save(conf.StateFile)
	return nil
}

func CommandUndo(conf Config, args []string) error {
	n := 1
	if len(args) == 3 {
		var err error
		n, err = strconv.Atoi(args[2])
		if err != nil {
			CommandHelp([]string{args[0], CMD_HELP, CMD_UNDO})
			return nil
		}
	}
	mustRunGitCmd(conf.Repo, "revert", "--no-gpg-sign", "--no-edit", "HEAD~"+strconv.Itoa(n)+"..")
	return nil
}

func CommandSync(conf Config) error {
	mustRunGitCmd(conf.Repo, "pull", "--ff", "--no-rebase", "--no-edit", "--commit")
	mustRunGitCmd(conf.Repo, "push")
	return nil
}

func CommandGit(conf Config, args []string) error {
	var gitArgs []string
	if len(args) > 2 {
		gitArgs = args[2:]
	}
	mustRunGitCmd(conf.Repo, gitArgs...)
	return nil
}

func CommandVersion() {
	fmt.Fprintf(stdout, "Version: %s\nGit commit: %s\nBuild date: %s\n", "Unknown", "Unknown", "Unknown")
}
EOF
