func (ts *TaskSet) removeTask(t *Task) {
	var out []*Task
	for _, x := range ts.tasks {
		if x != t {
			out = append(out, x)
		}
	}
	ts.tasks = out
	delete(ts.tasksByUUID, t.UUID)
	if t.ID > 0 {
		delete(ts.tasksByID, t.ID)
		delete(ts.usedIDs, t.ID)
	}
}

func CommandModify(conf Config, ctx, query Query) error {
	if !query.HasOperators() {
		return errors.New("no operations specified")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	if len(query.IDs) == 0 {
		ts.Filter(ctx)
		ts.FilterByStatus(OPEN_STATUSES...)
		tasks := ts.Tasks()
		if stdoutIsTTY() {
			confirmOrAbort("no IDs specified. Apply to all %d tasks in current ctx?", len(tasks))
		}
		for _, task := range tasks {
			task.Modify(query)
			task.normalise()
			task.WritePending = true
			ts.savePendingChanges()
			gitCommit(conf.Repo, "Modified %s", task)
		}
		return nil
	}
	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
		task.Modify(query)
		task.normalise()
		task.WritePending = true
		ts.savePendingChanges()
		gitCommit(conf.Repo, "Modified %s", task)
	}
	return nil
}

func CommandEdit(conf Config, ctx, query Query) error {
	if len(query.IDs) == 0 {
		return errors.New("no ID(s) specified")
	}
	ts := LoadTaskSet(conf.Repo, conf.IDsFile, false)
	for _, id := range query.IDs {
		task := ts.MustGetByID(id)
		data := task.MarshalYAMLEdit()
		var edited Task
		for {
			out := editBytes(data, makeTempFilename(task.ID, task.Summary, "yml"))
			edited = *task
			err := UnmarshalYAMLInto(out, &edited, true)
			if err == nil {
				break
			}
			fmt.Fprintf(stderr, "Failed to unmarshal %s\n", err)
			confirmOrAbort("Try again?")
		}
		edited.UUID = task.UUID
		edited.ID = task.ID
		newStatus := edited.Status
		if err := edited.Validate(); err != nil {
			return fmt.Errorf("%s, task %s", err, task.UUID)
		}
		edited.Status = task.Status
		*task = edited
		if err := ts.UpdateTask(task, newStatus); err != nil {
			return err
		}
		ts.savePendingChanges()
		gitCommit(conf.Repo, "Edited %s", task)
	}
	return nil
}

