		}
		if query.Text == "" {
			out := editBytes([]byte(task.Notes), makeTempFilename(task.ID, task.Summary, "md"))
			task.Notes = string(out)
		} else {
			task.Notes = appendNote(task.Notes, query.Text)
		}
		task.WritePending = true
		ts.savePendingChanges()
		gitCommit(conf.Repo, "Edit note %s", task)
	}
	return nil
