var schemesNoAuthority = []string{"bitcoin", "cid", "file", "magnet", "mailto", "mid", "sms", "tel", "xmpp"}

var urlRegex *regexp.Regexp

func reAnyOf(list []string) string {
	sorted := append([]string{}, list...)
	// longer alternatives first so that leftmost-first matching prefers them
	sort.Slice(sorted, func(i, j int) bool {
		if len(sorted[i]) != len(sorted[j]) {
			return len(sorted[i]) > len(sorted[j])
		}
		return sorted[i] < sorted[j]
	})
	quoted := make([]string, len(sorted))
	for i, s := range sorted {
		quoted[i] = regexp.QuoteMeta(s)
	}
	return "(?:" + strings.Join(quoted, "|") + ")"
}

func init() {
	tlds := reAnyOf(append(append(append([]string{}, tldList...), moreTLDs...), pseudoTLDs...))
	iriChar := `\\p{L}\\p{M}\\p{N}`
	endChar := iriChar + `/\\-_+&~%=#\\p{Sc}\\p{So}`
	midChar := endChar + `_*!;:,.?'@$\\[\\]()`
	pathCont := `[` + midChar + `]*[` + endChar + `]`
	scheme := `(?i:` + reAnyOf(schemesAuthority) + `://|` + reAnyOf(schemesNoAuthority) + `:)` + `(?:` + pathCont + `|[` + endChar + `])`
	iri := `[` + iriChar + `](?:[` + iriChar + `\\-]*[` + iriChar + `])?`
	domain := `(?:` + iri + `\\.)+`
	octet := `(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9][0-9]|[0-9])`
	ipv4 := octet + `\\.` + octet + `\\.` + octet + `\\.` + octet
	ipv6 := `\\[?(?:[0-9a-fA-F]{0,4}:){2,7}[0-9a-fA-F]{0,4}\\]?`
	site := domain + `(?:(?i:xn--[a-z0-9-]+)|(?i:` + tlds + `)|[^\\x00-\\x7F\\s\\pP\\pS\\d]{2,})`
	port := `(?::[0-9]*)?`
	path := `(?:/(?:` + pathCont + `)?)?`
	web := `(?:` + site + `|` + ipv4 + `|` + ipv6 + `)` + port + path
	email := `[a-zA-Z0-9._%\\-+]+@` + site
	urlRegex = regexp.MustCompile(scheme + `|` + email + `|` + web)
}

