package main

import (
	"math/rand"
	"testing"
	"unicode/utf8"
)

func TestYamlRoundTrip(t *testing.T) {
	pieces := []string{" ", "  ", "\n", "\n\n", "\t", "a", "b", ":", ": ", "#", " #", "-", "- ", "'", "\"", "\\", "[", "]", "{", "}", ",", "?", "|", ">", "&", "*", "!", "%", "@", "`", "é", "日本", "🎉", "\u2028", "\u00a0", "\u0085", "\r", "x", "word ", "true", "1", "0x", ".", "~", "null", "y", "---", "..."}
	r := rand.New(rand.NewSource(2))
	fails := 0
	for i := 0; i < 300000; i++ {
		n := r.Intn(30)
		s := ""
		for j := 0; j < n; j++ {
			s += pieces[r.Intn(len(pieces))]
		}
		if r.Intn(10) == 0 {
			for k := 0; k < 10; k++ {
				s += "lorem ipsum dolor "
			}
		}
		if !utf8.ValidString(s) {
			continue
		}
		task := Task{Summary: s, Notes: s, Tags: []string{s}, Priority: "P2", Project: s}
		data := task.MarshalYAMLFile()
		var back Task
		err := UnmarshalYAMLInto(data, &back, false)
		if err != nil || back.Summary != s || back.Notes != s || len(back.Tags) != 1 || back.Tags[0] != s || back.Project != s {
			fails++
			if fails < 10 {
				t.Errorf("roundtrip failed for %q: err=%v got summary=%q notes=%q\nyaml:\n%s", s, err, back.Summary, back.Notes, data)
			}
		}
	}
	if fails > 0 {
		t.Errorf("%d failures", fails)
	}
}
EOF
go test -run TestYamlRoundTrip . 2>&1 | head -60"}

